  const admin = await requireAdmin();
  await setSetting(DEDICATED_PUBLIC_FLAG, on ? "true" : "false");
  await recordAudit(admin.id, "dedicated.public_flag", on ? "on" : "off");
  revalidatePath("/admin/dedicated");
  return { ok: true };
}

export async function saveDedicatedItemControls(
  itemId: string,
  form: {
    visible: boolean;
    popularPinned?: boolean;
    displayName: string;
    markupPercent: string;
    markupFixed: string;
    overrideMonthly: string;
    setupPolicy: string;
    setupCustom: string;
    hiddenRegions: string[];
    adminNote: string;
  },
): Promise<Result> {
  const admin = await requireAdmin();
  try {
    const item = await db.dedicatedCatalogItem.findUnique({ where: { id: itemId }, select: { id: true } });
    if (!item) throw new Error("Item not found.");
    const pctRaw = form.markupPercent.trim();
    const pct = pctRaw === "" ? null : Number(pctRaw);
    if (pct != null && !Number.isFinite(pct)) throw new Error("Markup percent must be a number or blank.");
    const policy = form.setupPolicy.trim();
    if (policy !== "" && !isSetupPolicy(policy)) throw new Error("Unknown setup-fee policy.");
    const known = new Set(allDedicatedRegionCodes());
    const data = {
      visible: !!form.visible,
      popularPinned: !!form.popularPinned,
      displayName: form.displayName.trim().slice(0, 80),
      markupPercent: pct == null ? null : clampPercent(pct),
      markupFixedCents: centsFrom(form.markupFixed),
      overrideMonthlyCents: centsFrom(form.overrideMonthly),
      setupPolicy: policy === "" ? null : policy,
      setupCustomCents: centsFrom(form.setupCustom),
      hiddenRegions: form.hiddenRegions.filter((r) => known.has(r)),
      adminNote: form.adminNote.slice(0, 2000),
    };
    if (data.overrideMonthlyCents != null && data.overrideMonthlyCents < 0) throw new Error("Override price cannot be negative.");
    await db.dedicatedCatalogItem.update({ where: { id: itemId }, data });
    await recordAudit(admin.id, "dedicated.item.saved", `${itemId} ${JSON.stringify(data)}`);
    revalidatePath(`/admin/dedicated/catalog/${itemId}`);
    revalidatePath("/admin/dedicated");
    return { ok: true };
  } catch (e) {
    return fail(e);
  }
}

