const serverForm = z.object({
  userEmail: z.string().trim().email(),
  label: z.string().trim().min(1).max(80),
  hostname: z.string().trim().max(253).optional().default(""),
  catalogItemId: z.string().trim().optional().default(""),
  offerId: z.string().trim().optional().default(""),
  cpu: z.string().trim().min(1).max(120),
  cores: z.coerce.number().int().min(0).max(4096),
  threads: z.coerce.number().int().min(0).max(8192),
  ramGb: z.coerce.number().int().min(0).max(65536),
  storage: z.string().trim().max(200).default(""),
  bandwidth: z.string().trim().max(120).default(""),
  region: z.string().trim().min(1),
  datacenter: z.string().trim().max(40).optional().default(""),
  providerServiceName: z.string().trim().max(200).optional().default(""),
  costMonthly: z.string().optional().default(""),
  ipv4: z.string().optional().default(""),
  ipv6: z.string().optional().default(""),
  os: z.string().trim().max(120).optional().default(""),
  renewalDate: z.string().optional().default(""),
  renewalMonthly: z.string().optional().default(""),
  termMonths: z.coerce.number().int().min(1).max(36).default(1),
  setupFee: z.string().optional().default(""),
  invoiceIds: z.string().optional().default(""),
  notes: z.string().max(5000).optional().default(""),
});

export type DedicatedServerForm = z.input<typeof serverForm>;

const splitList = (s: string) => s.split(/[\s,]+/).map((x) => x.trim()).filter(Boolean);
const IPV4 = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;

function normalise(input: DedicatedServerForm) {
  const f = serverForm.parse(input);
  if (!allDedicatedRegionCodes().includes(f.region)) throw new Error("Unknown region.");
  const ipv4 = splitList(f.ipv4);
  const bad = ipv4.find((ip) => !IPV4.test(ip));
  if (bad) throw new Error(`Not an IPv4 address: ${bad}`);
  const ipv6 = splitList(f.ipv6);
  if (ipv6.some((ip) => !/^[0-9a-fA-F:]+(\/\d{1,3})?$/.test(ip))) throw new Error("Bad IPv6 entry.");
  const renewalDate = f.renewalDate ? new Date(f.renewalDate) : null;
  if (renewalDate && Number.isNaN(renewalDate.getTime())) throw new Error("Bad renewal date.");
  return {
    f,
    data: {
      label: f.label,
      hostname: f.hostname || null,
      catalogItemId: f.catalogItemId || null,
      offerId: f.offerId || null,
      cpu: f.cpu,
      cores: f.cores,
      threads: f.threads,
      ramGb: f.ramGb,
      storage: f.storage,
      bandwidth: f.bandwidth,
      region: f.region,
      datacenter: f.datacenter || null,
      providerServiceName: f.providerServiceName || null,
      costMonthlyCents: centsFrom(f.costMonthly),
      ipv4,
      ipv6,
      os: f.os || null,
      renewalDate,
      renewalMonthlyCents: centsFrom(f.renewalMonthly),
      termMonths: f.termMonths,
      setupFeeCents: centsFrom(f.setupFee) ?? 0,
      invoiceIds: splitList(f.invoiceIds),
      notes: f.notes,
    },
  };
}

export async function createDedicatedServer(input: DedicatedServerForm): Promise<Result> {
  const admin = await requireAdmin();
  try {
    const { f, data } = normalise(input);
    const user = await db.user.findUnique({ where: { email: f.userEmail.toLowerCase() }, select: { id: true } });
    if (!user) throw new Error("No customer account with that email.");
    const row = await db.dedicatedServer.create({ data: { ...data, userId: user.id, createdById: admin.id } });
    await event(row.id, admin.id, "created", `${data.label} for ${f.userEmail}`);
    revalidatePath("/admin/dedicated/servers");
    return { ok: true, id: row.id };
  } catch (e) {
    return fail(e);
  }
}

export async function updateDedicatedServer(id: string, input: DedicatedServerForm): Promise<Result> {
  const admin = await requireAdmin();
  try {
    const { f, data } = normalise(input);
    const cur = await db.dedicatedServer.findUnique({ where: { id }, select: { id: true, userId: true } });
    if (!cur) throw new Error("Not found.");
    const user = await db.user.findUnique({ where: { email: f.userEmail.toLowerCase() }, select: { id: true } });
    if (!user) throw new Error("No customer account with that email.");
    await db.dedicatedServer.update({ where: { id }, data: { ...data, userId: user.id } });
    await event(id, admin.id, "updated", user.id !== cur.userId ? `owner changed to ${f.userEmail}` : undefined);
    revalidatePath(`/admin/dedicated/servers/${id}`);
    return { ok: true, id };
  } catch (e) {
    return fail(e);
  }
}

export type LifecycleAction = "provisioning" | "provisioned" | "suspend" | "unsuspend" | "cancel";

/** Manual lifecycle. Records state only — the machine itself is handled by staff. */
export async function dedicatedLifecycle(id: string, action: LifecycleAction, reason = ""): Promise<Result> {
  const admin = await requireAdmin();
  try {
    const s = await db.dedicatedServer.findUnique({ where: { id }, select: { id: true, status: true } });
    if (!s) throw new Error("Not found.");
    const now = new Date();
    const next: Record<LifecycleAction, { from: string[]; data: Record<string, unknown> }> = {
      provisioning: { from: ["PENDING"], data: { status: "PROVISIONING" } },
      provisioned: { from: ["PENDING", "PROVISIONING"], data: { status: "ACTIVE", provisionedAt: now } },
      suspend: { from: ["ACTIVE"], data: { status: "SUSPENDED", suspendedAt: now, suspendReason: reason.slice(0, 500) || null } },
      unsuspend: { from: ["SUSPENDED"], data: { status: "ACTIVE", suspendedAt: null, suspendReason: null } },
      cancel: { from: ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"], data: { status: "CANCELLED", cancelledAt: now } },
    };
    const step = next[action];
    if (!step) throw new Error("Unknown action.");
    if (!step.from.includes(s.status)) throw new Error(`Cannot ${action} a ${s.status.toLowerCase()} server.`);
    await db.dedicatedServer.update({ where: { id }, data: step.data });
    await event(id, admin.id, action, reason || undefined);
    revalidatePath(`/admin/dedicated/servers/${id}`);
    return { ok: true };
  } catch (e) {
    return fail(e);
  }
}

/** Store credentials (encrypted at rest) and mark them delivered to the customer portal. */
export async function deliverDedicatedCredentials(id: string, username: string, secret: string): Promise<Result> {
  const admin = await requireAdmin();
  try {
    const u = username.trim().slice(0, 64);
    if (!u) throw new Error("Username required.");
    if (secret.length < 8) throw new Error("Password/secret must be at least 8 characters.");
    const s = await db.dedicatedServer.findUnique({ where: { id }, select: { id: true } });
    if (!s) throw new Error("Not found.");
    await db.dedicatedServer.update({ where: { id }, data: { credentialsUser: u, credentialsEnc: encryptSecret(secret), credentialsDeliveredAt: new Date() } });
    await event(id, admin.id, "credentials_delivered", `user ${u}`); // never the secret
    revalidatePath(`/admin/dedicated/servers/${id}`);
    return { ok: true };
  } catch (e) {
    return fail(e);
  }
}

export async function completeDedicatedRequest(requestId: string, status: "DONE" | "CANCELLED"): Promise<Result> {
  const admin = await requireAdmin();
  try {
    const r = await db.dedicatedServerRequest.findUnique({ where: { id: requestId }, select: { id: true, dedicatedServerId: true, kind: true, status: true } });
    if (!r || r.status !== "OPEN") throw new Error("Request not open.");
    await db.dedicatedServerRequest.update({ where: { id: requestId }, data: { status, doneById: admin.id, doneAt: new Date() } });
    await event(r.dedicatedServerId, admin.id, `request_${status.toLowerCase()}`, r.kind);
    revalidatePath(`/admin/dedicated/servers/${r.dedicatedServerId}`);
    return { ok: true };
  } catch (e) {
    return fail(e);
  }
}

export async function addDedicatedNote(id: string, note: string): Promise<Result> {
  const admin = await requireAdmin();
  const n = note.trim().slice(0, 2000);
  if (!n) return { ok: false, error: "Empty note." };
  const s = await db.dedicatedServer.findUnique({ where: { id }, select: { id: true } });
  if (!s) return { ok: false, error: "Not found." };
  await event(id, admin.id, "note", n);
  revalidatePath(`/admin/dedicated/servers/${id}`);
  return { ok: true };
}
"use server";

/**
 * ADMIN Phase 2 controls on a managed dedicated server: approve / reject a paid
 * extra-IP order, start the automated handover (install the ordered OS with the
 * customer's SSH key, then mark ACTIVE and notify), store a rescue password.
 * Every export calls requireAdmin(). Nothing here writes upstream: approval and
 * handover only enqueue DedicatedJob rows for the worker.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireAdmin } from "./auth";
import { recordAudit } from "./audit";
import { encryptSecret } from "./crypto-box";
import { approveIpOrder, IpOrderError, rejectIpOrder } from "./dedicated/ip-order";
import { isSshPublicKey, parseServerHostname } from "./dedicated/ops-core";

type R = { ok: true; message?: string } | { ok: false; error: string };
const err = (e: unknown): R => ({ ok: false, error: e instanceof IpOrderError || e instanceof Error ? e.message : "Failed" });

export async function adminApproveIpOrder(orderId: string): Promise<R> {
  try {
    const admin = await requireAdmin();
    const jobId = await approveIpOrder(orderId, admin.id);
    const o = await db.dedicatedIpOrder.findUnique({ where: { id: orderId }, select: { dedicatedServerId: true } });
    if (o) revalidatePath(`/admin/dedicated/servers/${o.dedicatedServerId}`);
    return { ok: true, message: `Approved. Worker job ${jobId} will place the order.` };
  } catch (e) {
    return err(e);
  }
}

export async function adminRejectIpOrder(orderId: string, reason: string): Promise<R> {
  try {
    const admin = await requireAdmin();
    await rejectIpOrder(orderId, admin.id, String(reason ?? ""));
    const o = await db.dedicatedIpOrder.findUnique({ where: { id: orderId }, select: { dedicatedServerId: true } });
    if (o) revalidatePath(`/admin/dedicated/servers/${o.dedicatedServerId}`);
    return { ok: true, message: "Rejected and refunded to the customer's wallet." };
  } catch (e) {
    return err(e);
  }
}

/**
 * The machine was bought and linked (providerServiceName set): install the OS the
 * customer ordered with their SSH key, then the worker marks it ACTIVE, fills the
 * IPs and tells the customer. The customer's key is the only login; Nxeon keeps
 * out-of-band control only.
 */
export async function adminStartHandover(serverId: string, input: { hostname?: string; sshKeyId?: string; osLabel?: string }): Promise<R> {
  try {
    const admin = await requireAdmin();
    const s = await db.dedicatedServer.findUnique({ where: { id: serverId } });
    if (!s) return { ok: false, error: "Not found" };
    if (!s.providerServiceName) return { ok: false, error: "Set the upstream service name first (Edit record)." };
    if (s.status !== "PENDING" && s.status !== "PROVISIONING") return { ok: false, error: "Handover is for a server that is not delivered yet." };
    const node = await db.node.findFirst({ where: { providerServerId: s.providerServiceName }, select: { name: true } });
    if (node) return { ok: false, error: `Refused: ${s.providerServiceName} is platform node ${node.name}.` };
    const running = await db.dedicatedJob.count({ where: { dedicatedServerId: s.id, status: { in: ["QUEUED", "RUNNING", "WAITING"] } } });
    if (running) return { ok: false, error: "A job is already running for this server." };
    const keys = await db.sshKey.findMany({ where: { userId: s.userId }, orderBy: { createdAt: "asc" } });
    const key = input.sshKeyId ? keys.find((k) => k.id === input.sshKeyId) : keys[0];
    if (!key || !isSshPublicKey(key.publicKey)) return { ok: false, error: "The customer has no valid SSH key on their account. Ask them to add one, or deliver credentials by hand." };
    const oc = (s.orderConfig ?? {}) as { osLabel?: string };
    const osLabel = (input.osLabel || oc.osLabel || s.os || "").trim();
    if (!osLabel) return { ok: false, error: "No operating system recorded for this order." };
    const hostname = parseServerHostname(input.hostname || s.hostname || `server-${s.id.slice(-6)}`);
    if (!hostname) return { ok: false, error: "Invalid hostname." };
    const job = await db.dedicatedJob.create({ data: { dedicatedServerId: s.id, userId: admin.id, kind: "HANDOVER", payload: { osLabel, hostname, sshKey: key.publicKey.trim() } } });
    await db.dedicatedServer.update({ where: { id: s.id }, data: { status: "PROVISIONING" } });
    await db.dedicatedServerEvent.create({ data: { dedicatedServerId: s.id, actorId: admin.id, action: "handover_queued", detail: `${job.id} os=${osLabel} key=${key.name}` } });
    await recordAudit(admin.id, "dedicated.handover.queued", `${s.id} job=${job.id}`);
    revalidatePath(`/admin/dedicated/servers/${s.id}`);
    return { ok: true, message: `Handover queued (job ${job.id}).` };
  } catch (e) {
    return err(e);
  }
}

export async function adminStoreRescueSecret(serverId: string, secret: string): Promise<R> {
  try {
    const admin = await requireAdmin();
    const v = String(secret ?? "").trim();
    if (v.length > 200) return { ok: false, error: "Too long." };
    await db.dedicatedServer.update({ where: { id: serverId }, data: { rescueSecretEnc: v ? encryptSecret(v) : null } });
    await db.dedicatedServerEvent.create({ data: { dedicatedServerId: serverId, actorId: admin.id, action: v ? "rescue_secret_stored" : "rescue_secret_cleared" } });
    revalidatePath(`/admin/dedicated/servers/${serverId}`);
    return { ok: true, message: v ? "Stored (encrypted). The customer can reveal it." : "Cleared." };
  } catch (e) {
    return err(e);
  }
}

