              {rows.map((r) => (
                <tr key={r.id} className="hover:bg-white/[0.02]">
                  <td className="px-3 py-2"><Link href={`/admin/dedicated/servers/${r.id}`} className="font-semibold text-slate-100 hover:text-white">{r.label}</Link><div className="text-[10px] text-slate-500">{r.ipv4[0] ?? "no IP"}{r.requests.length ? ` · ${r.requests.length} open request(s)` : ""}</div></td>
                  <td className="px-3 py-2 text-slate-300">{users.get(r.userId) ?? r.userId}</td>
                  <td className="px-3 py-2 text-slate-300">{r.cpu} · {r.ramGb} GB</td>
                  <td className="px-3 py-2 font-mono text-slate-400">{r.region}{r.datacenter ? ` (${r.datacenter})` : ""}</td>
                  <td className="px-3 py-2 font-mono text-[10px] text-slate-500">{r.providerServiceName ?? "—"}</td>
                  <td className="px-3 py-2"><Badge tone={STATUS_TONE[r.status]}>{r.status}</Badge></td>
                  <td className="px-3 py-2 text-right font-mono">{r.renewalMonthlyCents != null ? money(r.renewalMonthlyCents) : "—"}<div className="text-[10px] text-slate-500">{r.costMonthlyCents != null ? money(r.costMonthlyCents) : "—"}</div></td>
                  <td className="px-3 py-2 text-slate-400">{r.renewalDate?.toISOString().slice(0, 10) ?? "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      <DedicatedServerFormView regions={regions} initial={item ? {
        catalogItemId: item.id, cpu: `${item.cpuBrand} ${item.cpuModel}`, cores: item.cpuCores * item.cpuCount, threads: item.cpuThreads * item.cpuCount,
        ramGb: item.defaultRamGb ?? 0, storage: item.defaultStorage ?? "", bandwidth: item.defaultBandwidthMbps ? `${item.defaultBandwidthMbps >= 1000 ? item.defaultBandwidthMbps / 1000 + " Gbps" : item.defaultBandwidthMbps + " Mbps"} public bandwidth` : "",
        costMonthly: (item.monthlyCents / 100).toFixed(2),
      } : undefined} />
    </div>
  );
}
import Link from "next/link";
import { notFound } from "next/navigation";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { PageHeader, Badge } from "@/components/ui/primitives";
import { CredentialsForm, DedicatedServerFormView, LifecycleButtons, NoteForm, RequestDoneButtons } from "@/components/admin/dedicated/Controls";
import { DEDICATED_DC_REGIONS, customerDedicatedRegionLabel } from "@/lib/dedicated/regions";
import { margin, money } from "@/lib/dedicated/pricing";
import { offersAvailable } from "@/lib/dedicated/offer-link";
import { HandoverForm, IpOrderButtons, RescueSecretForm } from "@/components/admin/dedicated/OpsControls";
import { getSettingBool } from "@/lib/settings";

export const dynamic = "force-dynamic";

const TONE: Record<string, "brand" | "green" | "red" | "amber" | "slate"> = { PENDING: "slate", PROVISIONING: "brand", ACTIVE: "green", SUSPENDED: "amber", CANCELLED: "red" };

/**
 * ADMIN-ONLY: one managed dedicated server — record, manual lifecycle, credential
 * delivery, customer requests and the audit trail. Upstream service name /
 * datacenter / cost are admin-only fields.
 *
 * Future hook: `providerServiceName` has the same meaning as Node.providerServerId,
 * so the OVH admin-controls readers (branch feature/ovh-admin-controls,
 * lib/ovh-admin/read.ts readNodePanel / readIpPanel) can render a live panel
 * here once merged; nothing on this page calls the upstream API today.
 */
export default async function AdminDedicatedServer({ params }: { params: Promise<{ id: string }> }) {
  await requireAdmin();
  const { id } = await params;
  const s = await db.dedicatedServer.findUnique({ where: { id }, include: { events: { orderBy: { createdAt: "desc" }, take: 100 }, requests: { orderBy: { createdAt: "desc" } }, jobs: { orderBy: { createdAt: "desc" }, take: 25 }, ipOrders: { orderBy: { createdAt: "desc" } } } });
  if (!s) notFound();
  const [owner, invoices, item] = await Promise.all([
    db.user.findUnique({ where: { id: s.userId }, select: { id: true, email: true, name: true } }),
    s.invoiceIds.length ? db.invoice.findMany({ where: { id: { in: s.invoiceIds } }, select: { id: true, number: true, amountCents: true, status: true, createdAt: true, userId: true } }) : Promise.resolve([]),
    s.catalogItemId ? db.dedicatedCatalogItem.findUnique({ where: { id: s.catalogItemId }, select: { id: true, name: true, planCode: true, monthlyCents: true } }) : Promise.resolve(null),
  ]);
  const actors = new Map((await db.user.findMany({ where: { id: { in: [...s.events.map((e) => e.actorId), ...s.jobs.map((j) => j.userId)].filter((x): x is string => !!x) } }, select: { id: true, email: true } })).map((u) => [u.id, u.email]));
  const regions = Array.from(new Map(Object.values(DEDICATED_DC_REGIONS).map((r) => [r.code, { code: r.code, label: r.label }])).values());
  const m = s.renewalMonthlyCents != null && s.costMonthlyCents != null ? margin(s.costMonthlyCents, s.renewalMonthlyCents) : null;
  const [custKeys, dryRun, protectedNode] = await Promise.all([
    db.sshKey.findMany({ where: { userId: s.userId }, select: { id: true, name: true }, orderBy: { createdAt: "asc" } }),
    getSettingBool("dedicated_ovh_dry_run", true),
    s.providerServiceName ? db.node.findFirst({ where: { providerServerId: s.providerServiceName }, select: { name: true } }) : Promise.resolve(null),
  ]);
  type OrderOpt = { label?: string; productCode?: string } | null;
  const oc = (s.orderConfig ?? null) as null | { via?: string; planCode?: string; datacenter?: string | null; region?: string; stockAtOrder?: string; memory?: OrderOpt; storage?: OrderOpt; bandwidth?: OrderOpt; os?: string; osLabel?: string; money?: { termMonths: number; monthlyCents: number; totalCents: number; setupCents: number; taxCents: number } };

  return (
    <div className="space-y-6">
      <PageHeader title={<>{s.label} <Badge tone={TONE[s.status]}>{s.status}</Badge></>} sub={`${owner?.email ?? s.userId} · ${s.region} (${customerDedicatedRegionLabel(s.region)})`}>
        <Link href="/admin/dedicated/servers" className="btn-ghost py-1.5 text-xs">All servers</Link>
        <Link href={`/admin/preview/dedicated/dashboard?server=${s.id}`} className="btn-ghost py-1.5 text-xs">Preview customer dashboard</Link>
        {owner && <Link href={`/admin/users/${owner.id}`} className="btn-ghost py-1.5 text-xs">Customer</Link>}
      </PageHeader>

      {oc && (
        <div className="card space-y-3 border-brand-400/30 p-5">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <h3 className="text-sm font-semibold">Online order — build this by hand</h3>
            <span className="text-xs text-slate-400">paid via {oc.via} · {s.createdAt.toISOString().slice(0, 16).replace("T", " ")} UTC</span>
          </div>
          <dl className="grid gap-2 text-xs sm:grid-cols-3">
            <div><dt className="text-slate-500">Upstream plan (admin only)</dt><dd className="font-mono">{oc.planCode ?? "—"}</dd></div>
            <div><dt className="text-slate-500">Datacenter (admin only)</dt><dd className="font-mono">{oc.datacenter ?? "—"} → {oc.region}</dd></div>
            <div><dt className="text-slate-500">Stock at order</dt><dd>{oc.stockAtOrder ?? "—"}</dd></div>
            <div><dt className="text-slate-500">Memory</dt><dd>{oc.memory?.label ?? "default"} <span className="font-mono text-slate-500">{oc.memory?.productCode ?? ""}</span></dd></div>
            <div><dt className="text-slate-500">Storage</dt><dd>{oc.storage?.label ?? "default"} <span className="font-mono text-slate-500">{oc.storage?.productCode ?? ""}</span></dd></div>
            <div><dt className="text-slate-500">Bandwidth</dt><dd>{oc.bandwidth?.label ?? "default"}</dd></div>
            <div><dt className="text-slate-500">Operating system</dt><dd>{oc.osLabel ?? oc.os}</dd></div>
            <div><dt className="text-slate-500">Term</dt><dd>{oc.money?.termMonths === 12 ? "Annual" : "Monthly"} · {oc.money ? money(oc.money.monthlyCents) : "—"}/mo</dd></div>
            <div><dt className="text-slate-500">Paid today</dt><dd className="font-mono">{oc.money ? `${money(oc.money.totalCents)} (setup ${money(oc.money.setupCents)}, tax ${money(oc.money.taxCents)})` : "—"}</dd></div>
          </dl>
          <p className="text-[11px] text-slate-500">Customer was promised: online within 24 hours. Order upstream, then move to PROVISIONING, add IPs + credentials, and mark ACTIVE.</p>
        </div>
      )}

      <div className="grid gap-4 lg:grid-cols-3">
        <div className="card space-y-3 p-5 lg:col-span-2">
          <h3 className="text-sm font-semibold">Lifecycle (manual — records state only)</h3>
          <LifecycleButtons id={s.id} status={s.status} />
          <dl className="grid gap-2 pt-2 text-xs sm:grid-cols-3">
            <div><dt className="text-slate-500">Provisioned</dt><dd>{s.provisionedAt?.toISOString().slice(0, 16).replace("T", " ") ?? "—"}</dd></div>
            <div><dt className="text-slate-500">Suspended</dt><dd>{s.suspendedAt?.toISOString().slice(0, 10) ?? "—"}{s.suspendReason ? ` · ${s.suspendReason}` : ""}</dd></div>
            <div><dt className="text-slate-500">Cancelled</dt><dd>{s.cancelledAt?.toISOString().slice(0, 10) ?? "—"}</dd></div>
            <div><dt className="text-slate-500">Upstream service (admin only)</dt><dd className="font-mono">{s.providerServiceName ?? "—"}</dd></div>
            <div><dt className="text-slate-500">Upstream DC (admin only)</dt><dd className="font-mono">{s.datacenter ?? "—"}</dd></div>
            <div><dt className="text-slate-500">Catalogue item</dt><dd>{item ? <Link className="underline" href={`/admin/dedicated/catalog/${item.id}`}>{item.name} ({item.planCode})</Link> : "—"}</dd></div>
            <div><dt className="text-slate-500">Price / cost /mo</dt><dd className="font-mono">{s.renewalMonthlyCents != null ? money(s.renewalMonthlyCents) : "—"} / {s.costMonthlyCents != null ? money(s.costMonthlyCents) : "—"}{m ? ` · ${money(m.cents)} (${m.percent}%)` : ""}</dd></div>
            <div><dt className="text-slate-500">Renews</dt><dd>{s.renewalDate?.toISOString().slice(0, 10) ?? "—"} · every {s.termMonths} mo (manual)</dd></div>
            <div><dt className="text-slate-500">Offer</dt><dd>{s.offerId ? (offersAvailable() ? <Link className="underline" href={`/admin/offers?offer=${s.offerId}`}>{s.offerId}</Link> : s.offerId) : "—"}</dd></div>
          </dl>
        </div>
        <div className="card space-y-3 p-5">
          <h3 className="text-sm font-semibold">Credentials</h3>
          <CredentialsForm id={s.id} delivered={!!s.credentialsDeliveredAt} username={s.credentialsUser} />
          <h3 className="pt-2 text-sm font-semibold">Linked invoices</h3>
          {invoices.length === 0 ? <p className="text-xs text-slate-400">None linked. Add invoice ids in the form below.</p> : (
            <ul className="space-y-1 text-xs">
              {invoices.map((i) => (
                <li key={i.id} className="flex justify-between"><Link className="underline" href={`/admin/invoices?q=${i.number}`}>#{i.number}</Link><span>{money(i.amountCents)} · {i.status}{i.userId !== s.userId ? " · OTHER CUSTOMER" : ""}</span></li>
              ))}
            </ul>
          )}
        </div>
      </div>

      <div className="card space-y-4 p-5">
        <div className="flex flex-wrap items-center justify-between gap-2">
          <h3 className="text-sm font-semibold">Automation (Phase 2 worker jobs)</h3>
          <Badge tone={dryRun ? "amber" : "green"}>{dryRun ? "DRY RUN: nothing is sent upstream (Setting dedicated_ovh_dry_run)" : "LIVE upstream writes"}</Badge>
        </div>
        {protectedNode && <p className="text-xs text-red-300">The linked service name belongs to platform node {protectedNode.name}. Every automated action is refused for it.</p>}
        {(s.status === "PENDING" || s.status === "PROVISIONING") && (
          <HandoverForm id={s.id} linked={!!s.providerServiceName && !protectedNode} defaultHostname={s.hostname ?? `server-${s.id.slice(-6)}`} osLabel={((s.orderConfig ?? {}) as { osLabel?: string }).osLabel ?? s.os ?? ""} keys={custKeys} />
        )}
        <div>
          <h4 className="text-xs font-semibold text-slate-300">Extra-IP orders (approve before anything is bought)</h4>
          {s.ipOrders.length === 0 ? <p className="mt-1 text-xs text-slate-400">None.</p> : (
            <ul className="mt-1 divide-y divide-white/[0.04] text-xs">
              {s.ipOrders.map((o) => (
                <li key={o.id} className="flex flex-wrap items-center gap-3 py-2">
                  <Badge tone={o.status === "DONE" ? "green" : o.status === "PAID" ? "amber" : o.status === "REJECTED" || o.status === "FAILED" ? "red" : "brand"}>{o.status}</Badge>
                  <span>{o.quantity} IP{o.quantity > 1 ? "s" : ""} · paid {money(o.chargedCents)} · +{money(o.unitMonthlyCents * o.quantity)}/mo</span>
                  <span className="text-slate-500">{o.createdAt.toISOString().slice(0, 16).replace("T", " ")}</span>
                  {o.ips.length > 0 && <span className="font-mono text-slate-400">{o.ips.join(", ")}</span>}
                  <IpOrderButtons orderId={o.id} status={o.status} />
                </li>
              ))}
            </ul>
          )}
        </div>
        <div>
          <h4 className="text-xs font-semibold text-slate-300">Jobs</h4>
          {s.jobs.length === 0 ? <p className="mt-1 text-xs text-slate-400">None yet.</p> : (
            <ul className="mt-1 divide-y divide-white/[0.04] text-xs">
              {s.jobs.map((j) => (
                <li key={j.id} className="flex flex-wrap items-center gap-3 py-1.5">
                  <Badge tone={j.status === "DONE" ? "green" : j.status === "FAILED" ? "red" : "brand"}>{j.status}</Badge>
                  <b>{j.kind}</b>{j.dryRun && <span className="text-amber-300">dry run</span>}
                  <span className="text-slate-300">{j.step}{j.error ? ` / ${j.error}` : ""}</span>
                  <span className="text-slate-500">{j.createdAt.toISOString().slice(0, 16).replace("T", " ")} · {actors.get(j.userId) ?? j.userId}</span>
                </li>
              ))}
            </ul>
          )}
        </div>
        <RescueSecretForm id={s.id} stored={!!s.rescueSecretEnc} />
      </div>

      <div className="card p-5">
        <h3 className="text-sm font-semibold">Customer requests</h3>
        {s.requests.length === 0 ? <p className="mt-2 text-xs text-slate-400">None.</p> : (
          <ul className="mt-2 divide-y divide-white/[0.04] text-xs">
            {s.requests.map((r) => (
              <li key={r.id} className="flex flex-wrap items-center gap-3 py-2">
                <Badge tone={r.status === "OPEN" ? "amber" : r.status === "DONE" ? "green" : "slate"}>{r.status}</Badge>
                <b>{r.kind}</b>
                <span className="text-slate-400">{r.createdAt.toISOString().slice(0, 16).replace("T", " ")}</span>
                {r.ticketId && <Link className="underline" href={`/admin/support/${r.ticketId}`}>ticket</Link>}
                {r.detail && <span className="text-slate-300">“{r.detail}”</span>}
                {r.status === "OPEN" && <RequestDoneButtons requestId={r.id} />}
              </li>
            ))}
          </ul>
        )}
      </div>

      <DedicatedServerFormView id={s.id} regions={regions} initial={{
        userEmail: owner?.email ?? "", label: s.label, hostname: s.hostname ?? "", catalogItemId: s.catalogItemId ?? "", offerId: s.offerId ?? "",
        cpu: s.cpu, cores: s.cores, threads: s.threads, ramGb: s.ramGb, storage: s.storage, bandwidth: s.bandwidth, region: s.region,
        datacenter: s.datacenter ?? "", providerServiceName: s.providerServiceName ?? "", costMonthly: s.costMonthlyCents != null ? (s.costMonthlyCents / 100).toFixed(2) : "",
        ipv4: s.ipv4.join(", "), ipv6: s.ipv6.join(", "), os: s.os ?? "", renewalDate: s.renewalDate?.toISOString().slice(0, 10) ?? "",
        renewalMonthly: s.renewalMonthlyCents != null ? (s.renewalMonthlyCents / 100).toFixed(2) : "", termMonths: s.termMonths,
        setupFee: (s.setupFeeCents / 100).toFixed(2), invoiceIds: s.invoiceIds.join(", "), notes: s.notes,
      }} />

      <div className="card space-y-3 p-5">
        <h3 className="text-sm font-semibold">Audit trail</h3>
        <NoteForm id={s.id} />
        <ul className="divide-y divide-white/[0.04] text-xs">
          {s.events.map((e) => (
            <li key={e.id} className="flex flex-wrap gap-3 py-1.5">
              <span className="font-mono text-slate-500">{e.createdAt.toISOString().slice(0, 16).replace("T", " ")}</span>
              <b>{e.action}</b>
              <span className="text-slate-400">{e.actorId ? actors.get(e.actorId) ?? e.actorId : "system"}</span>
              {e.detail && <span className="text-slate-300">{e.detail}</span>}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

