export default async function DedicatedServerPage({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<{ ordered?: string; tab?: string }> }) {
  await requireDedicatedAccess();
  const user = await requireUser();
  const [{ id }, sp] = await Promise.all([params, searchParams]);
  const data = await loadCustomerServer(id, user.id);
  if (!data) notFound();
  return <DedicatedServerDashboard view={data.view} invoices={data.invoices} justOrdered={sp.ordered === "1"} balanceCents={user.balanceCents} initialTab={sp.tab} />;
}
/**
 * A customer's bare-metal servers as rows for the estate views: My Services
 * (lib/nx/services.ts -> components/customer/services) and the "Services"
 * card on the dashboard home (app/dashboard/page.tsx).
 *
 * GATED like every dedicated surface: an account that does not pass
 * lib/dedicated/gate.ts gets no rows (fail closed), so nothing about the
