  setupCents: number;
  /** Per-region Nxeon price: regional builds can cost more in some metros. */
  regions: { code: string; label: string; stock: PublicStock; monthlyCents: number; setupCents: number }[];
  ram: PublicOption[];
  disks: PublicOption[];
  network: PublicOption[];
};

export type CatalogSource = {
  id: string;
  range: string;
  displayName: string;
  cpuBrand: string;
  cpuModel: string;
  cpuCount: number;
  cpuCores: number;
  cpuThreads: number;
  cpuFrequencyGhz: number | null;
  cpuBoostGhz: number | null;
  defaultRamGb: number | null;
  defaultStorage: string | null;
  defaultBandwidthMbps: number | null;
  slaPercent: number | null;
  options: { family: string; label: string; isDefault: boolean; monthlyCents: number; removedAt?: Date | null }[];
};

const bw = (mbps: number | null) => (mbps == null ? "" : mbps >= 1000 ? `${+(mbps / 1000).toFixed(1)} Gbps` : `${mbps} Mbps`);

/**
 * One public catalogue card. `price` comes from catalog-view priceView (Nxeon
 * price only — cost and margin are deliberately not accepted as fields here).
 * `markOption` turns an option's upstream monthly cost into Nxeon's extra price.
 */
export function toPublicCatalogEntry(
  src: CatalogSource,
  price: Pick<PriceView, "sellMonthly" | "sellSetup">,
  regions: RegionRow[],
  markOption: (costCents: number) => number,
): PublicCatalogEntry {
  const cpu = brandSafe(`${src.cpuCount > 1 ? `${src.cpuCount}x ` : ""}${src.cpuBrand} ${src.cpuModel}`);
  const live = src.options.filter((o) => !o.removedAt);
  const gpu = live.find((o) => o.family === "gpu" && o.isDefault)?.label ?? null;
  const nx = { cpu, cpuCount: src.cpuCount, cores: src.cpuCores * Math.max(1, src.cpuCount), ramGb: src.defaultRamGb ?? 0, gpu };
  const family = nxFamily(nx);
  const t = { tier: family, blurb: NX_FAMILY_INFO[family].blurb, order: NX_FAMILY_INFO[family].order };
  const opts = (fam: string[]): PublicOption[] =>
    live
      .filter((o) => fam.includes(o.family))
      .map((o) => ({ label: brandSafe(o.label), extraMonthlyCents: o.monthlyCents > 0 ? markOption(o.monthlyCents) : 0, isDefault: o.isDefault }))
      .sort((a, b) => a.extraMonthlyCents - b.extraMonthlyCents);
  return {
    id: src.id,
    name: brandSafe(src.displayName) || nxName(nx),
    tier: t.tier,
    tierBlurb: t.blurb,
    tierOrder: t.order,
    cpu,
    cores: src.cpuCores * Math.max(1, src.cpuCount),
    threads: src.cpuThreads * Math.max(1, src.cpuCount),
    baseGhz: src.cpuFrequencyGhz,
    boostGhz: src.cpuBoostGhz,
    ramGb: src.defaultRamGb,
    storage: brandSafe(src.defaultStorage),
    bandwidth: src.defaultBandwidthMbps ? `${bw(src.defaultBandwidthMbps)} public bandwidth` : "",
    ddos: "Always-on DDoS protection",
    sla: src.slaPercent,
    monthlyCents: price.sellMonthly,
    setupCents: price.sellSetup,
    regions: regions
      .filter((r) => r.offered && !r.hidden)
      .map((r) => ({ code: r.code, label: r.customerLabel, stock: publicStock(r.stock), monthlyCents: price.sellMonthly, setupCents: price.sellSetup })),
    ram: opts(["memory"]),
    disks: opts(["storage", "system-storage"]),
    network: opts(["bandwidth"]).map((o) => ({ ...o, label: o.label.replace(/private bandwidth/i, "private network") })),
  };
}

