/**
 * REAL FUNDS vs PROMOTIONAL CREDIT in the wallet (owner decision 2026-10-08).
 *
 * Rule: welcome/signup credit and any promo, bonus, referral, coupon, gift or
 * goodwill credit may NOT pay for a dedicated (bare metal) server, neither the
 * first order nor a renewal, nor its extra IPs. Only real paid funds may: cash
 * that was topped up into the wallet, or a card charge.
 *
 * The wallet is one number (`User.balanceCents`). It never recorded which part of
 * it is promotional, so this module derives a SAFE bound:
 *
 *     promotional credit ever granted  P  = sum of the account's promotional CREDIT
 *                                           rows (tagged, or legacy by description),
 *                                           at least User.signupCreditCents
 *     spendable on dedicated           S  = max(0, balanceCents - P)
 *
 * Promotional credit is treated as never used up. That is deliberately
 * conservative: whatever the account spent on other products, and whatever was
 * refunded back into the wallet, `balance - P` can never exceed the real money
 * still in the wallet (balance = cash in + P + refunds - spend, and refunds never
 * exceed spend), so credit can never reach a dedicated purchase. The cost is that
 * an account which already spent its credit on a VPS still has P of its balance
 * held back from dedicated purchases; the card pays that part instead.
 *
 * New promotional credit rows are tagged `fundsKind: "PROMO"` where they are
 * written. Rows written before the tag existed are classified by their
 * description (every credit-granting description literal in the repo is listed
 * below; test/wallet-funds.test.ts fails if a new grant site is not tagged).
 *
 * Enforcement is in the debit itself (`debitRealFunds`): one conditional UPDATE
 * `balanceCents >= amount + P`, so no read-then-write race can spend credit.
 */
import type { Prisma, PrismaClient } from "@prisma/client";

/** WalletTransaction.fundsKind for promotional credit. */
export const PROMO_FUNDS = "PROMO" as const;

/**
 * Description prefixes of legacy (untagged) POSITIVE rows that are promotional
 * credit. Positive admin adjustments count as promotional (goodwill): a genuine
 * billing correction on a dedicated server goes through
 * lib/dedicated/billing-correction.ts, which writes real funds back.
 */
export const PROMO_DESCRIPTION_PREFIXES = [
  "Welcome credit",
  "Referral bonus",
  "Promo ",
  "Riddle prize",
  "Gift code redeemed",
  "Admin credit adjustment",
  "Admin balance adjustment",
  "Sandbox credit",
] as const;

export function isPromoDescription(description: string): boolean {
  return PROMO_DESCRIPTION_PREFIXES.some((p) => description.startsWith(p));
}

/** Prisma where-fragment for an account's promotional CREDIT rows (tagged or legacy). */
export function promoRowsWhere(userId: string): Prisma.WalletTransactionWhereInput {
  return {
    userId,
    amountCents: { gt: 0 },
    OR: [{ fundsKind: PROMO_FUNDS }, ...PROMO_DESCRIPTION_PREFIXES.map((p) => ({ fundsKind: null, description: { startsWith: p } }))],
  };
}

type Reader = Pick<PrismaClient, "walletTransaction" | "user"> | Prisma.TransactionClient;

/** Total promotional credit ever granted to the account (cents, >= signupCreditCents). */
export async function promoCreditGrantedCents(client: Reader, userId: string): Promise<number> {
  const [sum, u] = await Promise.all([
    client.walletTransaction.aggregate({ where: promoRowsWhere(userId), _sum: { amountCents: true } }),
    client.user.findUnique({ where: { id: userId }, select: { signupCreditCents: true } }),
  ]);
  return Math.max(sum._sum.amountCents ?? 0, u?.signupCreditCents ?? 0);
}

/** Pure: the part of a balance that real funds back, given the promo bound. */
export function spendableRealFunds(balanceCents: number, promoGrantedCents: number): { spendableCents: number; heldCreditCents: number } {
  const bal = Math.max(0, Math.round(balanceCents));
  const spendableCents = Math.max(0, bal - Math.max(0, Math.round(promoGrantedCents)));
  return { spendableCents, heldCreditCents: bal - spendableCents };
}

/** Real funds an account can spend on a dedicated server right now. */
export async function dedicatedSpendable(client: Reader, user: { id: string; balanceCents: number }): Promise<{ balanceCents: number; spendableCents: number; heldCreditCents: number }> {
  const promo = await promoCreditGrantedCents(client, user.id);
  return { balanceCents: user.balanceCents, ...spendableRealFunds(user.balanceCents, promo) };
}

export class PromoCreditNotAllowedError extends Error {
  constructor(public spendableCents: number, public heldCreditCents: number) {
    super("INSUFFICIENT_REAL_FUNDS");
    this.name = "PromoCreditNotAllowedError";
  }
}

/**
 * Debit `cents` from the wallet using REAL FUNDS ONLY (inside the caller's
 * transaction). Throws PromoCreditNotAllowedError when the real funds do not
 * cover it, even if the total balance (credit included) would.
 */
export async function debitRealFunds(tx: Prisma.TransactionClient, userId: string, cents: number): Promise<void> {
  if (cents <= 0) return;
  const promo = await promoCreditGrantedCents(tx, userId);
  const res = await tx.user.updateMany({
    where: { id: userId, balanceCents: { gte: cents + promo } },
    data: { balanceCents: { decrement: cents } },
  });
  if (res.count === 0) {
    const u = await tx.user.findUnique({ where: { id: userId }, select: { balanceCents: true } });
    const s = spendableRealFunds(u?.balanceCents ?? 0, promo);
    throw new PromoCreditNotAllowedError(s.spendableCents, s.heldCreditCents);
  }
}

/** Customer wording when credit was the only thing that could have paid. */
export const PROMO_CREDIT_NOTE =
  "Promotional and welcome credit can't be used for bare metal servers. Only funds you added to your wallet, or a card payment, can pay for them.";

