import Link from "next/link";
import type { Metadata } from "next";
import { requireDedicatedAccess } from "@/lib/dedicated/gate";
import { requireUser } from "@/lib/auth";
import { loadOrderBuild, loadOrderCatalog, orderPreviewAll } from "@/lib/dedicated/order";
import { BareMetalFlow } from "@/components/dedicated/flow/BareMetalFlow";
import { CatalogueHero } from "@/components/dedicated/flow/CatalogueHero";
import "@/components/dedicated/bm.css";

/**
 * Bare Metal Dedicated Servers: this page IS the order flow
 * (catalogue -> configure -> review -> pay; components/dedicated/flow/*).
 * A customer's own machines are listed under My Services and the dashboard
 * home, not here. `?build=<id>&region=<code>` opens a build directly (the
 * client keeps this in sync with history). 404 unless public OR a
 * private-preview account (lib/dedicated/gate.ts).
 */
export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Bare Metal Dedicated Servers", robots: { index: false, follow: false } };

export default async function BareMetalPage({ searchParams }: { searchParams: Promise<{ build?: string; region?: string; paid?: string }> }) {
  const access = await requireDedicatedAccess();
  const user = await requireUser();
  const sp = await searchParams;
  const previewAll = await orderPreviewAll(access.preview);
  const build = typeof sp.build === "string" && /^[a-z0-9]{8,40}$/i.test(sp.build) ? sp.build : null;
  const region = typeof sp.region === "string" && /^[a-z]{3}\d$/.test(sp.region) ? sp.region : null;
  const [cards, initialBuild] = await Promise.all([loadOrderCatalog(previewAll), build ? loadOrderBuild(build, previewAll) : Promise.resolve(null)]);
  return (
    <BareMetalFlow
      cards={cards}
      initialOpen={build ? { id: build, region } : null}
      initialBuild={initialBuild}
      balanceCents={user.balanceCents}
      email={user.email}
      preview={access.preview}
      previewAll={previewAll}
      hero={<CatalogueHero cards={cards} />}
      notice={sp.paid === "1" ? (
        <p className="bm-sub px-4 py-3 text-[12.5px]" role="status" style={{ color: "var(--bm-warn)", background: "var(--bm-warn-soft)" }}>
          Your payment went through and is safe in your wallet, but we couldn&apos;t finish placing the order. Our team has been alerted. <Link href="/dashboard/support" className="font-bold underline">Contact support</Link> and we&apos;ll sort it out.
        </p>
      ) : null}
    />
  );
}

