/**
 * PURE renewal policy for bare metal dedicated servers (auto-pay).
 * worker/dedicated-billing.ts runs it; test/dedicated-billing.test.ts covers it.
 *
 * Policy (owner rules 2026-10-08: no refunds, no discounts, real funds only):
 *   T-3d          warn once if the renewal looks like it will fail (no real funds, no card)
 *   T (renewalDate)
 *     cancelled   -> the server stops: CANCELLED (no charge, no refund, no proration)
 *     otherwise   -> charge renewalMonthlyCents x termMonths (+ tax), REAL funds first,
 *                    the saved card for the rest; advance renewalDate by one term
 *   T..T+grace    payment failed: keep running, retry once a day, tell the customer
 *   T+grace       SUSPENDED (unpaid). Paying later renews and lifts the suspension.
 *   T+terminate   CANCELLED (unpaid). Staff are told to end the machine upstream.
 * No discount of any kind is ever applied: the price is the frozen renewal price.
 */
import { addMonths, renewalLabel } from "./order-core";

export const DEDICATED_WARN_DAYS = 3;
export const DEDICATED_GRACE_DAYS_DEFAULT = 3;
export const DEDICATED_TERMINATE_DAYS_DEFAULT = 10;
/** Minimum gap between two payment attempts for the same period. */
export const DEDICATED_RETRY_MS = 20 * 60 * 60_000;

const DAY = 86_400_000;

export type RenewalRow = {
  status: string;
  renewalDate: Date | null;
  renewalMonthlyCents: number | null;
  termMonths: number;
  cancelAtPeriodEnd: boolean;
  renewalLastAttemptAt: Date | null;
  renewalWarnedFor: Date | null;
  suspendReason: string | null;
};

export type RenewalAction =
  | { kind: "none" }
  | { kind: "warn" }
  | { kind: "end-of-term" }
  | { kind: "charge" }
  | { kind: "suspend" }
  | { kind: "terminate" };

export const UNPAID_SUSPEND_REASON = "Unpaid renewal";

export function isUnpaidSuspension(r: Pick<RenewalRow, "status" | "suspendReason">): boolean {
  return r.status === "SUSPENDED" && (r.suspendReason ?? "").startsWith(UNPAID_SUSPEND_REASON);
}

/** The period total charged at renewal (before tax). Never discounted. */
export function renewalNetCents(r: Pick<RenewalRow, "renewalMonthlyCents" | "termMonths">): number {
  return Math.max(0, Math.round(r.renewalMonthlyCents ?? 0)) * Math.max(1, Math.round(r.termMonths || 1));
}

export function renewalTaxCents(netCents: number, ratePercent: number): number {
  return Number.isFinite(ratePercent) && ratePercent > 0 ? Math.round((netCents * ratePercent) / 100) : 0;
}

/** What to do with one server right now. */
export function renewalAction(r: RenewalRow, now: Date, cfg: { graceDays: number; terminateDays: number }): RenewalAction {
  if (!r.renewalDate || r.renewalMonthlyCents == null) return { kind: "none" };
  const billable = r.status === "ACTIVE" || isUnpaidSuspension(r);
  if (!billable) return { kind: "none" };
  const due = r.renewalDate.getTime();
  const t = now.getTime();
  if (t < due) {
    if (r.status !== "ACTIVE" || r.cancelAtPeriodEnd) return { kind: "none" };
    const warnedThisPeriod = r.renewalWarnedFor && r.renewalWarnedFor.getTime() === due;
    return due - t <= DEDICATED_WARN_DAYS * DAY && !warnedThisPeriod ? { kind: "warn" } : { kind: "none" };
  }
  if (r.cancelAtPeriodEnd) return { kind: "end-of-term" };
  if (t >= due + cfg.terminateDays * DAY) return { kind: "terminate" };
  const attemptedRecently = r.renewalLastAttemptAt && t - r.renewalLastAttemptAt.getTime() < DEDICATED_RETRY_MS && r.renewalLastAttemptAt.getTime() >= due;
  if (!attemptedRecently) return { kind: "charge" };
  if (r.status === "ACTIVE" && t >= due + cfg.graceDays * DAY) return { kind: "suspend" };
  return { kind: "none" };
}

/** Next period end after a successful renewal. */
export function nextRenewalDate(r: Pick<RenewalRow, "renewalDate" | "termMonths">): Date {
  return addMonths(r.renewalDate!, Math.max(1, r.termMonths || 1));
}

export function graceEndsAt(renewalDate: Date, graceDays: number): Date {
  return new Date(renewalDate.getTime() + graceDays * DAY);
}

export function terminatesAt(renewalDate: Date, terminateDays: number): Date {
  return new Date(renewalDate.getTime() + terminateDays * DAY);
}

export const renewalPriceText = (r: Pick<RenewalRow, "renewalMonthlyCents" | "termMonths">) => renewalLabel(r.renewalMonthlyCents ?? 0, r.termMonths);

