/**
 * AUTO-PAY renewals for bare metal dedicated servers (policy: lib/dedicated/billing-core.ts).
 *
 * Money rules (owner, 2026-10-08):
 *   - REAL funds only: the wallet part of a renewal comes from real paid funds
 *     (lib/wallet-funds.ts debitRealFunds); welcome/promo credit never pays.
 *   - No discounts of any kind: the charge is the frozen renewalMonthlyCents x term (+ tax).
 *   - No refunds: a cancelled server runs to the end of its paid period, then stops.
 *
 * Order of a renewal: real funds in the wallet first; the saved card is charged
 * off-session for exactly the shortfall (chargeSavedCardOffSession: permanent
 * per-period marker + Stripe idempotency key), the card money is credited to the
 * wallet (creditOffSessionCharge: UNIQUE paymentIntentId), and then ONE
 * transaction debits the total, writes the PAID invoice and advances renewalDate
 * with a compare-and-swap on the old renewalDate, so a re-run, a second worker or
 * an admin "Renew now" at the same moment can never charge one period twice.
 *
 * `dedicatedBillingSweep()` is called by worker/index.ts on a timer. Every row is
 * try/caught; one bad row never stops the sweep.
 */
import { db } from "../lib/db";
import { invoiceCreateData } from "../lib/invoices";
import { getSettingInt } from "../lib/settings";
import { walletSplit } from "../lib/wallet-split";
import { debitRealFunds, promoCreditGrantedCents, spendableRealFunds, PromoCreditNotAllowedError, PROMO_CREDIT_NOTE } from "../lib/wallet-funds";
import {
  DEDICATED_GRACE_DAYS_DEFAULT,
  DEDICATED_TERMINATE_DAYS_DEFAULT,
  UNPAID_SUSPEND_REASON,
  graceEndsAt,
  isUnpaidSuspension,
  nextRenewalDate,
  renewalAction,
  renewalNetCents,
  renewalPriceText,
  renewalTaxCents,
  terminatesAt,
} from "../lib/dedicated/billing-core";
import { termLabel, usd } from "../lib/dedicated/order-core";

const LOG = "[dedicated-billing]";
const ymd = (d: Date) => d.toISOString().slice(0, 10);

type CardUser = { id: string; email: string; name: string | null; stripeCustomerId: string | null; stripePaymentMethodId: string | null; cardBrand: string | null; cardLast4: string | null; cardExpMonth: number | null; cardExpYear: number | null };

export type CardCharge = (opts: { user: CardUser; amountCents: number; description: string; marker: string; idempotencyKey: string; metadata: Record<string, string> }) => Promise<{ ok: true; amountCents: number; paymentIntentId: string } | { ok: false; reason: string }>;

export type BillingDeps = {
  now: () => Date;
  /** Charge the saved card off-session and credit the wallet with what was taken. null = no chargeable card. */
  chargeCard: CardCharge | null;
  hasCard: (u: CardUser) => boolean;
  taxRatePercent: (u: { billingCountry: string | null; vatId: string | null }) => Promise<{ ratePercent: number; country: string }>;
  notify: (userId: string, title: string, body: string, href: string) => Promise<void>;
  notifyAdmins: (title: string, body: string, href: string) => Promise<void>;
};

async function defaultChargeCard(opts: Parameters<CardCharge>[0]): ReturnType<CardCharge> {
  const { chargeSavedCardOffSession, creditOffSessionCharge, cardDisplayLabel } = await import("../lib/stripe-cards");
  const r = await chargeSavedCardOffSession(opts);
  if (!r.ok) return { ok: false, reason: r.kind };
  const label = cardDisplayLabel({ brand: opts.user.cardBrand, last4: opts.user.cardLast4, expMonth: opts.user.cardExpMonth, expYear: opts.user.cardExpYear }) ?? "your saved card";
  await creditOffSessionCharge({ userId: opts.user.id, amountCents: r.amountCents, description: `Card payment for ${opts.description} (${label})`, paymentIntentId: r.paymentIntentId });
  return { ok: true, amountCents: r.amountCents, paymentIntentId: r.paymentIntentId };
}

export function defaultBillingDeps(): BillingDeps {
  return {
    now: () => new Date(),
    chargeCard: defaultChargeCard,
    hasCard: (u) => !!process.env.STRIPE_SECRET_KEY && !!u.stripeCustomerId && !!u.stripePaymentMethodId,
    taxRatePercent: async (u) => {
      const { taxContextForUser } = await import("../lib/tax");
      const t = await taxContextForUser(u);
      return { ratePercent: t.ratePercent, country: t.country };
    },
    notify: async (userId, title, body, href) => {
      await db.notification.create({ data: { userId, title, body, href } }).catch(() => {});
    },
    notifyAdmins: async (title, body, href) => {
      const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
      if (admins.length) await db.notification.createMany({ data: admins.map((a) => ({ userId: a.id, title, body, href })) }).catch(() => {});
    },
  };
}

async function config() {
  const [graceDays, terminateDays] = await Promise.all([
    getSettingInt("dedicated_renewal_grace_days", DEDICATED_GRACE_DAYS_DEFAULT),
    getSettingInt("dedicated_renewal_terminate_days", DEDICATED_TERMINATE_DAYS_DEFAULT),
  ]);
  const g = Math.max(1, Math.min(14, graceDays));
  return { graceDays: g, terminateDays: Math.max(g + 1, Math.min(60, terminateDays)) };
}

const serverHref = (id: string) => `/dashboard/dedicated/${id}`;
const adminHref = (id: string) => `/admin/dedicated/servers/${id}`;

async function event(serverId: string, action: string, detail: string) {
  await db.dedicatedServerEvent.create({ data: { dedicatedServerId: serverId, action, detail: detail.slice(0, 500) } }).catch(() => {});
  await db.auditLog.create({ data: { userId: null, action: `dedicated.billing.${action}`, detail: `${serverId} ${detail}`.slice(0, 2000) } }).catch(() => {});
}

export type RenewResult = { ok: true; invoiceId: string; chargedCents: number; viaCardCents: number; nextRenewal: Date } | { ok: false; reason: string; already?: boolean };

/**
 * Try to renew ONE server for its current period. Used by the sweep and by the
 * admin "Renew now" control. Idempotent per period (CAS on renewalDate).
 */
export async function renewDedicatedServer(serverId: string, deps: BillingDeps = defaultBillingDeps(), actor: string | null = null): Promise<RenewResult> {
  const s = await db.dedicatedServer.findUnique({ where: { id: serverId } });
  if (!s || !s.renewalDate || s.renewalMonthlyCents == null) return { ok: false, reason: "Not renewable (no renewal date or price)." };
  if (!(s.status === "ACTIVE" || isUnpaidSuspension(s))) return { ok: false, reason: `Not renewable while ${s.status.toLowerCase()}.` };
  if (s.cancelAtPeriodEnd) return { ok: false, reason: "Cancelled at period end: not renewed." };
  const user = await db.user.findUnique({ where: { id: s.userId } });
  if (!user) return { ok: false, reason: "Customer not found." };
  const now = deps.now();
  const period = s.renewalDate;
  const net = renewalNetCents(s);
  const tax = await deps.taxRatePercent({ billingCountry: user.billingCountry ?? null, vatId: user.vatId ?? null });
  const taxCents = renewalTaxCents(net, tax.ratePercent);
  const total = net + taxCents;
  const next = nextRenewalDate(s);
  const what = `Bare Metal Dedicated Server renewal — ${s.label}`.slice(0, 190);

  await db.dedicatedServer.updateMany({ where: { id: s.id, renewalDate: period }, data: { renewalLastAttemptAt: now, renewalAttempts: { increment: 1 }, ...(s.renewalFailedAt ? {} : {}) } });

  // 1) real funds in the wallet first, the card for the shortfall
  const promo = await promoCreditGrantedCents(db, user.id);
  const { spendableCents } = spendableRealFunds(user.balanceCents, promo);
  let viaCardCents = 0;
  if (spendableCents < total) {
    const split = walletSplit({ dueCents: total, balanceCents: spendableCents, useWallet: true });
    const cardUser: CardUser = { id: user.id, email: user.email, name: user.name, stripeCustomerId: user.stripeCustomerId, stripePaymentMethodId: user.stripePaymentMethodId, cardBrand: user.cardBrand, cardLast4: user.cardLast4, cardExpMonth: user.cardExpMonth, cardExpYear: user.cardExpYear };
    if (!deps.chargeCard || !deps.hasCard(cardUser) || split.cardCents <= 0) {
      return failed(s, deps, now, "no-funds", spendableCents, total);
    }
    const r = await deps.chargeCard({
      user: cardUser,
      amountCents: split.cardCents,
      description: `${s.label} bare metal renewal`,
      marker: `renew:ded:${s.id}:${period.toISOString()}`,
      idempotencyKey: `nxeon_dedrenew_${s.id}_${period.getTime()}_${split.cardCents}`,
      metadata: { nxeonDedicatedServerId: s.id, nxeonPeriodStart: period.toISOString(), nxeonKind: "dedicated_renewal" },
    });
    if (!r.ok) return failed(s, deps, now, `card-${r.reason}`, spendableCents, total);
    viaCardCents = r.amountCents;
  }

  // 2) one transaction: CAS the period, debit REAL funds, PAID invoice, ledger row
  try {
    const invoiceId = await db.$transaction(async (tx) => {
      const flipped = await tx.dedicatedServer.updateMany({
        where: { id: s.id, renewalDate: period, cancelAtPeriodEnd: false },
        data: { renewalDate: next, renewalFailedAt: null, renewalAttempts: 0, renewalWarnedFor: null, ...(isUnpaidSuspension(s) ? { status: "ACTIVE", suspendedAt: null, suspendReason: null } : {}) },
      });
      if (flipped.count !== 1) throw new AlreadyRenewed();
      await debitRealFunds(tx, user.id, total);
      await tx.walletTransaction.create({ data: { userId: user.id, amountCents: -total, description: what } });
      const inv = await tx.invoice.create({
        data: invoiceCreateData({
          userId: user.id,
          description: what,
          status: "PAID",
          lineItems: [{ description: `${s.label}: ${termLabel(s.termMonths)} renewal ${ymd(period)} to ${ymd(next)} (${renewalPriceText(s)})`, qty: 1, unitCents: net, amountCents: net }],
          taxCents,
          taxRatePercent: tax.ratePercent,
          taxCountry: taxCents > 0 ? tax.country || null : null,
          period: { start: period, end: next },
        }),
        select: { id: true },
      });
      await tx.dedicatedServer.update({ where: { id: s.id }, data: { invoiceIds: { push: inv.id } } });
      return inv.id;
    });
    await event(s.id, "renewed", `${usd(total)} (${viaCardCents ? `${usd(viaCardCents)} by card, ` : ""}rest from real wallet funds) invoice ${invoiceId}; next ${ymd(next)}${actor ? ` by ${actor}` : ""}${isUnpaidSuspension(s) ? "; suspension lifted" : ""}`);
    await deps.notify(s.userId, `${s.label} renewed`, `We charged ${usd(total)}. Next renewal ${ymd(next)}.`, serverHref(s.id));
    return { ok: true, invoiceId, chargedCents: total, viaCardCents, nextRenewal: next };
  } catch (e) {
    if (e instanceof AlreadyRenewed) return { ok: false, reason: "Already renewed for this period.", already: true };
    if (e instanceof PromoCreditNotAllowedError) return failed(s, deps, now, "no-real-funds", e.spendableCents, total);
    throw e;
  }
}

class AlreadyRenewed extends Error {}

async function failed(s: { id: string; userId: string; label: string; renewalDate: Date | null; status: string; renewalFailedAt: Date | null }, deps: BillingDeps, now: Date, why: string, spendableCents: number, total: number): Promise<RenewResult> {
  const cfg = await config();
  const due = s.renewalDate!;
  await db.dedicatedServer.updateMany({ where: { id: s.id, renewalDate: due, renewalFailedAt: null }, data: { renewalFailedAt: now } });
  const first = !s.renewalFailedAt;
  if (first) {
    await event(s.id, "renewal_failed", `${why}: due ${usd(total)}, real funds ${usd(spendableCents)}`);
    await deps.notify(s.userId, `Renewal payment failed for ${s.label}`, `We couldn't collect ${usd(total)}. Add funds to your wallet or update your card. Your server keeps running until ${ymd(graceEndsAt(due, cfg.graceDays))}, then it is suspended. ${PROMO_CREDIT_NOTE}`, serverHref(s.id));
    await deps.notifyAdmins(`Bare metal renewal failed: ${s.label}`, `${why}; due ${usd(total)}. Suspends ${ymd(graceEndsAt(due, cfg.graceDays))}.`, adminHref(s.id));
  }
  if (s.status === "ACTIVE" && now.getTime() >= graceEndsAt(due, cfg.graceDays).getTime()) await suspend(s, deps, cfg);
  return { ok: false, reason: why };
}

async function suspend(s: { id: string; userId: string; label: string; renewalDate: Date | null }, deps: BillingDeps, cfg: { terminateDays: number }) {
  const r = await db.dedicatedServer.updateMany({ where: { id: s.id, status: "ACTIVE" }, data: { status: "SUSPENDED", suspendedAt: new Date(), suspendReason: `${UNPAID_SUSPEND_REASON} (due ${ymd(s.renewalDate!)})` } });
  if (r.count !== 1) return;
  await event(s.id, "suspended_unpaid", `due ${ymd(s.renewalDate!)}`);
  await deps.notify(s.userId, `${s.label} is suspended`, `The renewal is unpaid. Pay it to bring the server back. If it is still unpaid on ${ymd(terminatesAt(s.renewalDate!, cfg.terminateDays))}, the server and its data are removed.`, serverHref(s.id));
  await deps.notifyAdmins(`Bare metal suspended (unpaid): ${s.label}`, "Suspended in our records. Restrict the machine upstream if policy requires it.", adminHref(s.id));
}

async function endServer(s: { id: string; userId: string; label: string; renewalDate: Date | null }, deps: BillingDeps, reason: "cancelled" | "unpaid") {
  const r = await db.dedicatedServer.updateMany({ where: { id: s.id, status: { in: ["ACTIVE", "SUSPENDED"] } }, data: { status: "CANCELLED", cancelledAt: new Date() } });
  if (r.count !== 1) return;
  await event(s.id, reason === "cancelled" ? "ended_at_period_end" : "terminated_unpaid", `period ended ${ymd(s.renewalDate!)}`);
  await deps.notify(s.userId, `${s.label} has ended`, reason === "cancelled" ? "Your cancellation took effect at the end of the paid period." : "The renewal stayed unpaid, so the server was ended.", serverHref(s.id));
  // The machine itself is ended upstream by staff (never automatically from here).
  await deps.notifyAdmins(`End bare metal machine upstream: ${s.label}`, `${reason === "cancelled" ? "Customer cancellation reached the end of the paid period" : "Unpaid past the termination date"}. Stop the upstream renewal and wipe the machine.`, adminHref(s.id));
}

/** One sweep. Returns counts for logs/tests. */
export async function dedicatedBillingSweep(deps: BillingDeps = defaultBillingDeps()): Promise<{ renewed: number; failed: number; warned: number; ended: number; suspended: number }> {
  const out = { renewed: 0, failed: 0, warned: 0, ended: 0, suspended: 0 };
  const now = deps.now();
  const cfg = await config();
  const soon = new Date(now.getTime() + 4 * 86_400_000);
  const rows = await db.dedicatedServer.findMany({ where: { status: { in: ["ACTIVE", "SUSPENDED"] }, renewalDate: { not: null, lt: soon } }, take: 500 });
  for (const s of rows) {
    try {
      const a = renewalAction(s, now, cfg);
      if (a.kind === "warn") {
        const user = await db.user.findUnique({ where: { id: s.userId } });
        if (!user) continue;
        const promo = await promoCreditGrantedCents(db, user.id);
        const real = spendableRealFunds(user.balanceCents, promo).spendableCents;
        const due = renewalNetCents(s);
        const card = deps.hasCard({ id: user.id, email: user.email, name: user.name, stripeCustomerId: user.stripeCustomerId, stripePaymentMethodId: user.stripePaymentMethodId, cardBrand: user.cardBrand, cardLast4: user.cardLast4, cardExpMonth: user.cardExpMonth, cardExpYear: user.cardExpYear });
        await db.dedicatedServer.updateMany({ where: { id: s.id, renewalDate: s.renewalDate }, data: { renewalWarnedFor: s.renewalDate } });
        if (real < due && !card) {
          await deps.notify(s.userId, `${s.label} renews on ${ymd(s.renewalDate!)}`, `The renewal is ${renewalPriceText(s)} and your wallet's real funds (${usd(real)}) won't cover it, and no card is saved. Add funds or a card so the server isn't suspended. ${PROMO_CREDIT_NOTE}`, serverHref(s.id));
          out.warned++;
        }
      } else if (a.kind === "end-of-term") {
        await endServer(s, deps, "cancelled");
        out.ended++;
      } else if (a.kind === "terminate") {
        await endServer(s, deps, "unpaid");
        out.ended++;
      } else if (a.kind === "suspend") {
        await suspend(s, deps, cfg);
        out.suspended++;
      } else if (a.kind === "charge") {
        const r = await renewDedicatedServer(s.id, deps);
        if (r.ok) out.renewed++;
        else if (!r.already) out.failed++;
      }
    } catch (e) {
      console.error(`${LOG} server ${s.id} failed`, e);
    }
  }
  return out;
}

