/**
 * DB-BACKED CACHE of a delivered server's live panel (power, boot mode,
 * hardware, network, IPs with rDNS/firewall, install images).
 *
 * Rule (owner, 2026-10-08): a customer never waits on a supplier API call to see
 * their dashboard. Customer reads (lib/actions-dedicated-ops.ts loadDedicatedPanel)
 * only read `DedicatedServer.liveSnapshot` + `liveFetchedAt`. Refreshing is the
 * worker's job (worker/dedicated-live.ts), triggered by:
 *   - a viewer seeing a snapshot older than LIVE_STALE_MS (or none yet),
 *   - the explicit Refresh button,
 *   - any finished DedicatedJob (the machine changed),
 *   - a slow background pass (LIVE_BACKGROUND_MS) for servers nobody is viewing.
 * Single-flight: `requestLiveRefresh` is one conditional UPDATE, so 50 viewers
 * opening the page at once produce ONE refresh request; the worker clears it.
 * A failed refresh keeps the last good snapshot and records `liveError`.
 *
 * The snapshot is the brand-safe `DedicatedLive` projection (lib/dedicated/live.ts):
 * no upstream names or service identifiers are stored in it.
 */
import type { Prisma } from "@prisma/client";
import { db } from "../db";
import type { DedicatedLive } from "./live";

/** Older than this: shown, but a refresh is requested. */
export const LIVE_STALE_MS = 2 * 60_000;
/** The worker refreshes every linked server at least this often. */
export const LIVE_BACKGROUND_MS = 30 * 60_000;
/** A refresh request nobody served for this long may be re-requested. */
export const LIVE_REQUEST_RETRY_MS = 60_000;
/** One refresh never takes the worker longer than this. */
export const LIVE_REFRESH_TIMEOUT_MS = 25_000;

export type LiveCacheRow = { liveSnapshot: Prisma.JsonValue | null; liveFetchedAt: Date | null; liveError: string | null; liveRefreshRequestedAt: Date | null };

export type LiveCacheView = {
  live: DedicatedLive | null;
  fetchedAt: string | null;
  /** True when the snapshot is older than LIVE_STALE_MS (or missing). */
  stale: boolean;
  /** A refresh is requested and not served yet. */
  refreshing: boolean;
  /** Customer-safe text when the last refresh failed (stale data is still shown). */
  error: string | null;
};

export function isLiveSnapshot(v: unknown): v is DedicatedLive {
  return !!v && typeof v === "object" && (v as { ok?: unknown }).ok === true && Array.isArray((v as { ips?: unknown }).ips);
}

/** Pure view of the cached columns. */
export function liveCacheView(r: LiveCacheRow, now: number): LiveCacheView {
  const live = isLiveSnapshot(r.liveSnapshot) ? r.liveSnapshot : null;
  const fetched = r.liveFetchedAt?.getTime() ?? 0;
  const requested = r.liveRefreshRequestedAt?.getTime() ?? 0;
  return {
    live,
    fetchedAt: r.liveFetchedAt ? r.liveFetchedAt.toISOString() : null,
    stale: !live || now - fetched > LIVE_STALE_MS,
    refreshing: requested > fetched && now - requested < LIVE_REQUEST_RETRY_MS * 3,
    error: r.liveError ? "Live status couldn't be updated just now. Showing the last known state." : null,
  };
}

/**
 * Ask the worker to refresh one server's snapshot. Single-flight: only writes
 * when no request is pending (or the pending one is older than the retry window).
 * Returns true when this call placed the request.
 */
export async function requestLiveRefresh(serverId: string, now = new Date()): Promise<boolean> {
  const retryBefore = new Date(now.getTime() - LIVE_REQUEST_RETRY_MS);
  const n = await db.$executeRaw`
    UPDATE "DedicatedServer" SET "liveRefreshRequestedAt" = ${now}
    WHERE id = ${serverId}
      AND ("liveRefreshRequestedAt" IS NULL
           OR "liveRefreshRequestedAt" <= COALESCE("liveFetchedAt", 'epoch'::timestamp)
           OR "liveRefreshRequestedAt" < ${retryBefore})`;
  return n === 1;
}

/** Brand-safe IP blocks from the snapshot (for validating customer input without a supplier call). */
export function snapshotCidrs(live: DedicatedLive | null): string[] {
  return live ? live.ips.map((i) => i.cidr).filter((c): c is string => typeof c === "string") : [];
}

/** Write a fresh snapshot (worker). Clears the request it served. */
export async function storeLiveSnapshot(serverId: string, live: DedicatedLive, at: Date): Promise<void> {
  await db.dedicatedServer.update({ where: { id: serverId }, data: { liveSnapshot: live as unknown as Prisma.InputJsonValue, liveFetchedAt: at, liveError: null } });
}

/** Record a failed refresh (worker). Keeps the last good snapshot. */
export async function storeLiveError(serverId: string, error: string, at: Date): Promise<void> {
  // Mark the request as served (fetchedAt untouched would keep "refreshing" forever),
  // so stamp the request time back to just before now.
  await db.dedicatedServer.update({ where: { id: serverId }, data: { liveError: error.slice(0, 300), liveRefreshRequestedAt: new Date(at.getTime() - LIVE_REQUEST_RETRY_MS * 3) } });
}

