/**
 * Worker sweep that keeps the bare metal live-panel cache warm
 * (lib/dedicated/live-cache.ts). READ-ONLY: GETs through the same getter the
 * panel used to call inline (lib/dedicated/live.ts dedicatedGetter: the demo
 * mock when NXEON_DEDICATED_OVH_MOCK=1 on a non-production process, else the
 * GET-only admin transport, else nothing).
 *
 * Each tick (every 5 s): up to 3 servers, requested ones first, then any linked
 * ACTIVE/SUSPENDED server whose snapshot is older than LIVE_BACKGROUND_MS. One
 * tick at a time per process (in-flight guard); each refresh is time-boxed, and a
 * failure keeps the last good snapshot.
 */
import { db } from "../lib/db";
import { dedicatedGetter, readDedicatedLive, type Getter } from "../lib/dedicated/live";
import { LIVE_BACKGROUND_MS, LIVE_REFRESH_TIMEOUT_MS, storeLiveError, storeLiveSnapshot } from "../lib/dedicated/live-cache";

let inFlight = false;

function timeout<T>(p: Promise<T>, ms: number): Promise<T> {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error(`timed out after ${ms} ms`)), ms);
    p.then((v) => { clearTimeout(t); resolve(v); }, (e) => { clearTimeout(t); reject(e); });
  });
}

/** Refresh one server now (worker, or a test). Returns true when a snapshot was stored. */
export async function refreshDedicatedLive(serverId: string, get: Getter | null = dedicatedGetter(), now: () => Date = () => new Date()): Promise<boolean> {
  const s = await db.dedicatedServer.findUnique({ where: { id: serverId }, select: { id: true, providerServiceName: true, status: true } });
  if (!s?.providerServiceName || !get) return false;
  try {
    const live = await timeout(readDedicatedLive(s.providerServiceName, get), LIVE_REFRESH_TIMEOUT_MS);
    await storeLiveSnapshot(s.id, live, now());
    return true;
  } catch (e) {
    await storeLiveError(s.id, String((e as Error)?.message ?? e), now());
    return false;
  }
}

export async function dedicatedLiveRefreshTick(deps: { get?: Getter | null; now?: () => Date } = {}): Promise<number> {
  if (inFlight) return 0;
  const get = deps.get === undefined ? dedicatedGetter() : deps.get;
  if (!get) return 0;
  inFlight = true;
  try {
    const now = (deps.now ?? (() => new Date()))();
    const requested = await db.$queryRaw<{ id: string }[]>`
      SELECT id FROM "DedicatedServer"
      WHERE "providerServiceName" IS NOT NULL AND status IN ('ACTIVE','SUSPENDED')
        AND "liveRefreshRequestedAt" IS NOT NULL
        AND "liveRefreshRequestedAt" > COALESCE("liveFetchedAt", 'epoch'::timestamp)
        AND "liveRefreshRequestedAt" > ${new Date(now.getTime() - 5 * 60_000)}
      ORDER BY "liveRefreshRequestedAt" ASC LIMIT 3`;
    let ids = requested.map((r) => r.id);
    if (ids.length < 3) {
      const old = await db.dedicatedServer.findMany({
        where: { providerServiceName: { not: null }, status: { in: ["ACTIVE", "SUSPENDED"] }, id: { notIn: ids }, OR: [{ liveFetchedAt: null }, { liveFetchedAt: { lt: new Date(now.getTime() - LIVE_BACKGROUND_MS) } }] },
        orderBy: { liveFetchedAt: { sort: "asc", nulls: "first" } },
        select: { id: true },
        take: 3 - ids.length,
      });
      ids = [...ids, ...old.map((o) => o.id)];
    }
    let n = 0;
    for (const id of ids) if (await refreshDedicatedLive(id, get, deps.now)) n++;
    return n;
  } finally {
    inFlight = false;
  }
}

