("""export async function runJobStep(job: JobInput, server: ServerInput, deps: StepDeps): Promise<StepResult> {
  const g = guardJob(job, server, deps.protectedServiceNames);""","""export async function runJobStep(job: JobInput, server: ServerInput, deps: StepDeps): Promise<StepResult> {
