/* ---------------- automatic server order (auto deployment) ---------------- */

/**
 * Payload of a SERVER_ORDER job, written by lib/dedicated/auto-order.ts from the
 * PAID order (never before the customer's payment is committed). ADMIN-ONLY data.
 */
export type ServerOrderPayload = {
  catalog: "eco" | "baremetalServers";
  planCode: string;
  datacenter: string;
  /** Option plan codes (memory, storage, bandwidth...) the customer picked. */
  options: string[];
  subsidiary: string;
  /** What we expect the supplier's first invoice to be (monthly + setup, cents, ex tax). */
  expectedFirstCents: number;
  /** Refuse to check out when the supplier price is more than this % above expectations. */
  maxDriftPercent: number;
};

const toCents = (v: unknown): number | null => {
  const n = typeof v === "number" ? v : typeof v === "string" ? Number(v) : NaN;
  return Number.isFinite(n) ? Math.round(n * 100) : null;
};

/** Configuration value for one required cart field (null when we can't fill it). */
export function serverOrderConfigValue(label: string, p: Pick<ServerOrderPayload, "datacenter">, allowed: unknown): string | null {
  const list = Array.isArray(allowed) ? allowed.filter((x): x is string => typeof x === "string") : [];
  let v: string | null = null;
  if (label === "dedicated_datacenter") v = p.datacenter;
  else if (label === "dedicated_os") v = list.find((x) => /^none_64/.test(x)) ?? "none_64.en"; // installed by HANDOVER with the customer's key
  else if (label === "region") v = list.length === 1 ? list[0] : null;
  if (v && list.length && !list.includes(v)) return null;
  return v;
}

/**
 * Order the physical machine upstream for a PAID order: cart -> plan (+ options)
 * -> required configuration (datacenter, no OS) -> PRICE CHECK -> checkout with
 * the account's payment method -> wait for delivery -> read the new service name
 * -> chain the HANDOVER. Only reached when Setting dedicated_auto_order=true;
 * dry run sends nothing. A price above expectations HOLDS the order for staff.
 * Re-entrancy: once `state.orderId` exists no second checkout can ever happen.
 */
async function serverOrderStep(job: JobInput, server: ServerInput, deps: StepDeps): Promise<StepResult> {
  const { client } = deps;
  const p = (job.payload ?? {}) as ServerOrderPayload;
  const st = job.state ?? {};
  const target = `order:${server.id}`;
  if (server.status !== "PENDING" && server.status !== "PROVISIONING") return fail("Refused", "This server is no longer waiting for a machine.");

  if (st.phase === "wait") {
    const status = await client.get(`/me/order/${enc(String(st.orderId))}/status`).catch(() => null);
    if (status === "cancelled" || status === "cancelling") return fail("Order cancelled", "The machine order was cancelled upstream. Staff must re-order or fix it by hand.", { server: { upstreamOrderStatus: String(status) } });
    if (status !== "delivered") return { status: "WAITING", step: status === "delivering" ? "Machine being delivered" : "Waiting for the data center to deliver the machine", progress: status === "delivering" ? 70 : 50, state: { ...st, upstreamStatus: status ?? st.upstreamStatus }, effects: status && status !== st.upstreamStatus ? { server: { upstreamOrderStatus: String(status) } } : undefined };
    const ids = await client.get(`/me/order/${enc(String(st.orderId))}/details`).catch(() => []);
    let sn = "";
    for (const d of Array.isArray(ids) ? ids.slice(0, 20) : []) {
      const det = await client.get(`/me/order/${enc(String(st.orderId))}/details/${enc(String(d))}`).catch(() => null);
      const dom = typeof det?.domain === "string" ? det.domain.trim() : "";
      if (/^[a-z0-9][a-z0-9.-]{2,120}$/i.test(dom) && !dom.startsWith("*")) { sn = dom; break; }
    }
    if (!sn) return { status: "WAITING", step: "Waiting for the machine's details", progress: 80, state: st };
    if (deps.protectedServiceNames.has(sn) || deps.protectedServiceNames.has(sn.toLowerCase())) return fail("Refused", `Delivered service ${sn} is platform infrastructure; not linking it.`);
    return done("Machine delivered", { server: { providerServiceName: sn, statusProvisioning: true, upstreamOrderStatus: "delivered" }, chainHandover: true });
  }

  if (!p.planCode || !p.datacenter || (p.catalog !== "eco" && p.catalog !== "baremetalServers")) return fail("Refused", "The order is missing its build details. Order this machine by hand.");
  if (job.dryRun) return done(`Dry run: would order ${p.planCode} in ${p.datacenter}${p.options?.length ? ` with ${p.options.join(", ")}` : ""}. Nothing was bought.`);

  const cart = await client.write({ action: "dedicated.server.cart", method: "POST", path: "/order/cart", body: { ovhSubsidiary: p.subsidiary || deps.ovhSubsidiary || "WE", description: `nxeon-srv-${server.id}` }, target });
  if (!cart.ok) return fail("Order failed", cart.error);
  const cartId = String(cart.response?.cartId ?? "");
  if (!cartId) return fail("Order failed", "No cart id returned.");
  const c = `/order/cart/${enc(cartId)}`;
  const asg = await client.write({ action: "dedicated.server.cart.assign", method: "POST", path: `${c}/assign`, target });
  if (!asg.ok) return fail("Order failed", asg.error);
  const item = await client.write({ action: "dedicated.server.cart.item", method: "POST", path: `${c}/${p.catalog}`, body: { planCode: p.planCode, duration: "P1M", pricingMode: "default", quantity: 1 }, target });
  if (!item.ok) return fail("Order failed", item.error);
  const itemId = item.response?.itemId;
  if (itemId == null) return fail("Order failed", "No cart item id returned.");
  for (const opt of p.options ?? []) {
    const o = await client.write({ action: "dedicated.server.cart.option", method: "POST", path: `${c}/${p.catalog}/options`, body: { itemId, planCode: opt, duration: "P1M", pricingMode: "default", quantity: 1 }, target });
    if (!o.ok) return fail("Order failed", `Option ${opt}: ${o.error}`);
  }
  const req = await client.get(`${c}/item/${enc(String(itemId))}/requiredConfiguration`).catch(() => []);
  for (const rc of Array.isArray(req) ? req : []) {
    const label = String(rc?.label ?? "");
    const value = serverOrderConfigValue(label, p, rc?.allowedValues);
    if (!value) {
      if (rc?.required) return fail("Order failed", `Can't fill the required order detail "${label}". Order this machine by hand.`);
      continue;
    }
    const w = await client.write({ action: "dedicated.server.cart.config", method: "POST", path: `${c}/item/${enc(String(itemId))}/configuration`, body: { label, value }, target });
    if (!w.ok) return fail("Order failed", w.error);
  }
  // Price check BEFORE paying: GET checkout is a preview and spends nothing.
  const preview = await client.get(`${c}/checkout`).catch(() => null);
  const priced = toCents(preview?.prices?.withoutTax?.value);
  if (priced == null) return fail("Held for staff", "Couldn't read the supplier price before ordering. Nothing was bought; check and order by hand.");
  const cap = Math.round(Math.max(0, p.expectedFirstCents) * (1 + Math.max(0, p.maxDriftPercent) / 100));
  if (p.expectedFirstCents > 0 && priced > cap) return fail("Held for staff", `The supplier price is ${(priced / 100).toFixed(2)} vs expected ${(p.expectedFirstCents / 100).toFixed(2)} (over the ${p.maxDriftPercent}% limit). Nothing was bought.`);
  const co = await client.write({ action: "dedicated.server.checkout", method: "POST", path: `${c}/checkout`, body: { autoPayWithPreferredPaymentMethod: true, waiveRetractationPeriod: true }, target, dangerous: true });
  if (!co.ok) return fail("Order failed", co.error);
  const orderId = co.response?.orderId;
  if (orderId == null) return fail("Order failed", "Checkout returned no order id. Check the supplier account before retrying.");
  return { status: "WAITING", step: "Waiting for the data center to deliver the machine", progress: 40, state: { phase: "wait", orderId, pricedCents: priced }, effects: { server: { upstreamOrderId: String(orderId), upstreamOrderStatus: "checkout" } } };
}
