/**
 * DEDICATED SERVERS ARE NON-REFUNDABLE (owner rule 2026-10-08). There is no
 * refund tool for them: the generic admin invoice refund refuses dedicated
 * invoices (lib/actions-admin-billing.ts refundPayment -> isDedicatedInvoice),
 * cancellation runs to the end of the paid period (no proration), and the old
 * extra-IP "Reject & refund" is gone.
 *
 * This module is the ONE separate, audited way staff may give money back on a
 * dedicated server, and only to correct OUR mistake:
 *   BILLING_ERROR  we charged the wrong amount or twice;
 *   NOT_DELIVERED  the customer paid for something we never delivered (an extra-IP
 *                  order we could not fulfil, a machine we could not source).
 * It credits the customer's WALLET (never the card), as real funds; needs a reason
 * (10+ chars) and the server's name typed as confirmation; is capped at what was
 * actually paid on this server minus earlier corrections; and is recorded in
 * DedicatedBillingCorrection + DedicatedServerEvent + AuditLog.
 */
import { db } from "../db";

export const CORRECTION_KINDS = ["BILLING_ERROR", "NOT_DELIVERED"] as const;
export type CorrectionKind = (typeof CORRECTION_KINDS)[number];

export class CorrectionError extends Error {}

/** True when an invoice belongs to a dedicated server (description prefix or linked id). */
export function isDedicatedInvoiceDescription(description: string | null | undefined): boolean {
  return /^Bare Metal Dedicated Server\b/.test(description ?? "");
}

/** Does this invoice belong to a dedicated server? (description, or listed on a DedicatedServer row). */
export async function isDedicatedInvoice(inv: { id: string; description?: string | null }): Promise<boolean> {
  if (isDedicatedInvoiceDescription(inv.description)) return true;
  const n = await db.dedicatedServer.count({ where: { invoiceIds: { has: inv.id } } });
  return n > 0;
}

export const DEDICATED_NO_REFUND_ADMIN =
  "Dedicated servers are non-refundable. Refunds are blocked for this invoice. If we made a billing error or did not deliver, use \"Billing correction\" on the dedicated server's admin page (audited, credits the wallet).";

/** Pure: how much may still be corrected. */
export function correctionCap(paidCents: number, correctedCents: number): number {
  return Math.max(0, Math.round(paidCents) - Math.max(0, Math.round(correctedCents)));
}

export async function applyBillingCorrection(args: {
  serverId: string;
  adminId: string;
  kind: string;
  amountCents: number;
  reason: string;
  confirm: string;
  ipOrderId?: string | null;
  invoiceId?: string | null;
}): Promise<{ id: string }> {
  if (!(CORRECTION_KINDS as readonly string[]).includes(args.kind)) throw new CorrectionError("Pick BILLING_ERROR or NOT_DELIVERED.");
  const reason = String(args.reason ?? "").trim().slice(0, 500);
  if (reason.length < 10) throw new CorrectionError("Give a reason of at least 10 characters (it is shown to the customer and kept in the audit log).");
  const amount = Math.round(Number(args.amountCents));
  if (!Number.isFinite(amount) || amount <= 0) throw new CorrectionError("Enter an amount above zero.");
  const s = await db.dedicatedServer.findUnique({ where: { id: args.serverId } });
  if (!s) throw new CorrectionError("Not found.");
  if (String(args.confirm ?? "").trim() !== s.label) throw new CorrectionError(`Type the server name "${s.label}" exactly to confirm.`);
  const [paid, prior] = await Promise.all([
    s.invoiceIds.length ? db.invoice.aggregate({ where: { id: { in: s.invoiceIds }, userId: s.userId, status: "PAID" }, _sum: { amountCents: true } }) : Promise.resolve({ _sum: { amountCents: 0 } }),
    db.dedicatedBillingCorrection.aggregate({ where: { dedicatedServerId: s.id }, _sum: { amountCents: true } }),
  ]);
  const cap = correctionCap(paid._sum.amountCents ?? 0, prior._sum.amountCents ?? 0);
  if (amount > cap) throw new CorrectionError(`At most ${(cap / 100).toFixed(2)} can be corrected on this server (what was paid, minus earlier corrections).`);
  if (args.invoiceId && !s.invoiceIds.includes(args.invoiceId)) throw new CorrectionError("That invoice is not linked to this server.");

  const id = await db.$transaction(async (tx) => {
    if (args.ipOrderId) {
      const o = await tx.dedicatedIpOrder.findUnique({ where: { id: args.ipOrderId } });
      if (!o || o.dedicatedServerId !== s.id) throw new CorrectionError("IP order not found on this server.");
      if (o.status !== "PAID" && o.status !== "FAILED") throw new CorrectionError(`This IP order is ${o.status.toLowerCase()}; it can't be corrected now.`);
      if (amount !== o.chargedCents) throw new CorrectionError("A not-delivered IP order is corrected for exactly what was charged.");
      const flipped = await tx.dedicatedIpOrder.updateMany({ where: { id: o.id, status: o.status }, data: { status: "REJECTED", rejectReason: reason.slice(0, 300), approvedById: args.adminId } });
      if (flipped.count !== 1) throw new CorrectionError("Already handled.");
    }
    const c = await tx.dedicatedBillingCorrection.create({
      data: { dedicatedServerId: s.id, userId: s.userId, kind: args.kind, amountCents: amount, reason, ipOrderId: args.ipOrderId ?? null, invoiceId: args.invoiceId ?? null, adminId: args.adminId },
      select: { id: true },
    });
    await tx.user.update({ where: { id: s.userId }, data: { balanceCents: { increment: amount } } });
    // Real funds (untagged): it returns money the customer actually paid.
    await tx.walletTransaction.create({ data: { userId: s.userId, amountCents: amount, description: `Billing correction — ${s.label}: ${reason}`.slice(0, 190) } });
    await tx.dedicatedServerEvent.create({ data: { dedicatedServerId: s.id, actorId: args.adminId, action: "billing_correction", detail: `${c.id} ${args.kind} ${amount}c${args.ipOrderId ? ` ip-order ${args.ipOrderId}` : ""}: ${reason}`.slice(0, 500) } });
    await tx.auditLog.create({ data: { userId: args.adminId, action: "dedicated.billing_correction", detail: `${c.id} server=${s.id} kind=${args.kind} amount=${amount} ${reason}`.slice(0, 2000) } });
    return c.id;
  });
  await db.notification
    .create({ data: { userId: s.userId, title: "Billing correction on your bare metal server", body: `We credited ${(amount / 100).toFixed(2)} USD to your wallet for ${s.label}: ${reason}`, href: `/dashboard/dedicated/${s.id}` } })
    .catch(() => {});
  return { id };
}

