cd /tank/dev-worktrees/bm-ops && cat >> lib/actions-dedicated-ops-admin.ts <<'EOF'

/* ---------------- release hardening (bm-ops 2026-10-08) ---------------- */

/**
 * The ONLY money-back control on a dedicated server: a billing correction for OUR
 * error or a non-delivery (lib/dedicated/billing-correction.ts). Not a refund.
 */
export async function adminBillingCorrection(serverId: string, input: { kind: string; amount: string; reason: string; confirm: string; invoiceId?: string }): Promise<R> {
  try {
    const admin = await requireAdmin();
    const { applyBillingCorrection } = await import("./dedicated/billing-correction");
    const cents = Math.round(Number(String(input.amount ?? "").replace(/[$,\s]/g, "")) * 100);
    const r = await applyBillingCorrection({ serverId, adminId: admin.id, kind: input.kind, amountCents: cents, reason: input.reason, confirm: input.confirm, invoiceId: input.invoiceId || null });
    revalidatePath(`/admin/dedicated/servers/${serverId}`);
    return { ok: true, message: `Correction ${r.id} recorded and credited to the customer's wallet.` };
  } catch (e) {
    return err(e);
  }
}

/** Re-run a FAILED job as a new job (typed confirmation: the server name). */
export async function adminRetryJob(jobId: string, confirm: string): Promise<R> {
  try {
    const admin = await requireAdmin();
    const j = await db.dedicatedJob.findUnique({ where: { id: jobId }, include: { server: { select: { id: true, label: true, status: true } } } });
    if (!j) return { ok: false, error: "Not found" };
    if (j.status !== "FAILED") return { ok: false, error: "Only a failed job can be retried." };
    if (String(confirm ?? "").trim() !== j.server.label) return { ok: false, error: `Type the server name "${j.server.label}" to confirm. Check the machine first: the failed attempt may have partly run.` };
    const running = await db.dedicatedJob.count({ where: { dedicatedServerId: j.dedicatedServerId, status: { in: ["QUEUED", "RUNNING", "WAITING"] } } });
    if (running) return { ok: false, error: "Another job is still running for this server." };
    const payload = (j.payload ?? {}) as { ipOrderId?: string };
    const created = await db.$transaction(async (tx) => {
      if (j.kind === "IP_ORDER") {
        if (!payload.ipOrderId) throw new Error("IP order missing.");
        const f = await tx.dedicatedIpOrder.updateMany({ where: { id: payload.ipOrderId, status: "FAILED" }, data: { status: "APPROVED" } });
        if (f.count !== 1) throw new Error("The IP order is not in a failed state.");
      }
      const n = await tx.dedicatedJob.create({ data: { dedicatedServerId: j.dedicatedServerId, userId: admin.id, kind: j.kind, payload: (j.payload ?? {}) as object } });
      if (j.kind === "IP_ORDER" && payload.ipOrderId) await tx.dedicatedIpOrder.update({ where: { id: payload.ipOrderId }, data: { jobId: n.id } });
      await tx.dedicatedServerEvent.create({ data: { dedicatedServerId: j.dedicatedServerId, actorId: admin.id, action: "job_retried", detail: `${j.id} -> ${n.id} ${j.kind}` } });
      await tx.auditLog.create({ data: { userId: admin.id, action: "dedicated.job.retry", detail: `${j.id} -> ${n.id} ${j.kind} server=${j.dedicatedServerId}` } });
      return n;
    });
    revalidatePath(`/admin/dedicated/servers/${j.dedicatedServerId}`);
    return { ok: true, message: `Retry queued (job ${created.id}).` };
  } catch (e) {
    return err(e);
  }
}

/** Ask the worker to refresh this server's cached live state from the supplier (read-only GETs). */
export async function adminRefreshLive(serverId: string): Promise<R> {
  try {
    const admin = await requireAdmin();
    const { requestLiveRefresh } = await import("./dedicated/live-cache");
    const placed = await requestLiveRefresh(serverId);
    await recordAudit(admin.id, "dedicated.live.refresh_requested", serverId);
    revalidatePath(`/admin/dedicated/servers/${serverId}`);
    return { ok: true, message: placed ? "Refresh requested; the worker reads it within a few seconds." : "A refresh is already on its way." };
  } catch (e) {
    return err(e);
  }
}

/** Tell the customer again where their login/IP is (in-app + the ready email). Never includes the secret. */
export async function adminResendDelivery(serverId: string): Promise<R> {
  try {
    const admin = await requireAdmin();
    const s = await db.dedicatedServer.findUnique({ where: { id: serverId } });
    if (!s) return { ok: false, error: "Not found" };
    if (s.status !== "ACTIVE") return { ok: false, error: "Only a delivered (ACTIVE) server." };
    await db.notification.create({ data: { userId: s.userId, title: `${s.label}: your login and IP addresses`, body: "They are on the server page. Use your SSH key, or reveal the stored login there.", href: `/dashboard/dedicated/${s.id}` } });
    const { DEDICATED_OVH_MOCK } = await import("./dedicated/ovh-mock");
    let emailed = false;
    if (!DEDICATED_OVH_MOCK) {
      const u = await db.user.findUnique({ where: { id: s.userId }, select: { email: true, name: true } });
      if (u) {
        const { sendMail } = await import("./mailer");
        const base = process.env.APP_URL ?? "https://nxeon.cloud";
        emailed = await sendMail({ to: u.email, template: "dedicated_server_ready", userId: s.userId, vars: { name: u.name.split(" ")[0] || "there", label: s.label, ip: s.ipv4[0] ?? "", url: `${base}/dashboard/dedicated/${s.id}` } }).catch(() => false);
