 * decrement only what remains (the rest is a real-cash write-off) and note it.
 */
export async function refundPayment(
  _prev: unknown,
  formData: FormData
): Promise<{ error?: string; message?: string }> {
  const admin = await requireArea("billing");

  const userId = String(formData.get("userId") ?? "");
  const reason = String(formData.get("reason") ?? "").trim().slice(0, 200);
  const cents = parseAmountCents(formData.get("amount"));
  // The invoice this refund is FOR. The UI has always rendered the control under a
  // heading naming one invoice, pre-filled with that invoice's total — but the id
  // was never sent, so the action guessed its Stripe target as "most recent top-up,
  // any amount". Refunding a $24 March invoice therefore issued $24 against the
  // customer's $200 July top-up, left the invoice PAID, and invited the next admin
  // to refund it all over again.
  const invoiceId = String(formData.get("invoiceId") ?? "").trim();

  if (!userId) return { error: "Missing customer." };
  if (cents === null || cents < 0) return { error: "Enter a positive refund amount (max $50,000)." };

  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user) return { error: "Customer not found." };

  // Resolve and validate the target invoice when one was supplied.
  let invoice = null as Awaited<ReturnType<typeof db.invoice.findUnique>>;
  // How much of the invoice was already refunded WHEN WE READ IT. Two jobs: it is
  // the compare-and-swap anchor for the write below, and it is what makes the
  // Stripe idempotency key describe a STEP of the refund rather than an amount.
  let alreadyRefunded = 0;
  if (invoiceId) {
    invoice = await db.invoice.findUnique({ where: { id: invoiceId } });
    if (!invoice) return { error: "Invoice not found." };
    if (invoice.userId !== userId) return { error: "That invoice belongs to a different customer." };
    alreadyRefunded = invoice.refundedCents ?? 0;
    const refundable = Math.max(0, invoice.amountCents - alreadyRefunded);
    if (refundable === 0) {
      return { error: `Invoice already fully refunded ($${(alreadyRefunded / 100).toFixed(2)}).` };
    }
    if (cents > refundable) {
      return {
        error: `That exceeds what's left on this invoice — $${(refundable / 100).toFixed(2)} refundable ($${(alreadyRefunded / 100).toFixed(2)} already refunded).`,
      };
    }
  }

  // --- Route the refund back to the ORIGINAL card for this charge ---
  let method: "stripe" | "wallet" = "wallet";
  let stripeRefundId: string | null = null;
  if (stripeConfigured()) {
    // Prefer the charge that actually paid THIS invoice; only fall back to the
    // latest top-up when no invoice was specified (the standalone refund form).
    const tx = await db.walletTransaction.findFirst({
      where: invoice
        ? {

    ? {
        userId,
        description: { contains: "Stripe payment (cs_" },
        createdAt: { lte: invoice.paidAt ?? invoice.createdAt },
      }
    : { userId, description: { contains: "Stripe payment (cs_" } },
  orderBy: { createdAt: "desc" },
});
const sessionId = sessionIdFrom(tx?.description);
if (sessionId) {
  try {
    const session = await stripe().checkout.sessions.retrieve(sessionId);
    const pi =
      typeof session.payment_intent === "string"
        ? session.payment_intent
        : session.payment_intent?.id;
    if (pi) {
      // Idempotency key derived from the target, the amount AND how much of
      // this invoice had already been refunded when this request read it.
      //
      // The first two alone (`refund:<target>:<pi>:<cents>`) deduplicated two
      // submits — which is the point — but they ALSO deduplicated two genuinely
      // different refunds that happened to be the same size. Two $10 partial
      // refunds against a $100 invoice are a completely ordinary support
      // sequence, and Stripe replayed the first refund for the second: ONE $10
      // refund reached the card while this action debited the customer's wallet
      // $10 twice and recorded $20 against the invoice. The customer was $10
      // down, and the two systems agreed with each other about it.
      //
      // `alreadyRefunded` is 0 then 10 across those two calls, so they are
      // distinct requests; a true double-submit reads the same value and still
      // collapses to one refund. (Standalone refunds with no invoice keep the
      // old shape — there is no per-target running total to anchor to.)
      const refund = await stripe().refunds.create(
        { payment_intent: pi, amount: cents },
        {
          idempotencyKey: invoiceId
            ? `refund:${invoiceId}:${pi}:${alreadyRefunded}:${cents}`
            : `refund:${userId}:${pi}:${cents}`,
        }
      );

