    if (!int(i.cpuCores) || i.cpuCores < 1 || i.cpuCores > 64) e.push("vCPU must be 1–64.");
    if (!int(i.ramMB) || i.ramMB < 512 || i.ramMB > 512 * 1024) e.push("RAM must be 0.5–512 GB.");
    if (!int(i.diskGB) || i.diskGB < 10 || i.diskGB > 8000) e.push("Disk must be 10–8000 GB.");
