import { MONEY_BACK_TERMS } from "@/lib/refund-policy";
import type { LegalSection } from "@/components/marketing/LegalDoc";

/**
 * TERMS — the single source for this document, rendered by the live
 * app/legal/terms page and the new marketing site (app/nxm). Edit here only.
 */
export const DOC = {
  title: "Terms of Service",
  metaTitle: "Terms of Service",
  description: "The terms governing your use of the Nxeon cloud VPS hosting platform.",
  updated: "September 27, 2026",
  route: "/legal/terms",
  intro: "Please read these Terms carefully. They govern your access to and use of Nxeon and describe the rights and responsibilities that apply to both of us.",
};

export const sections: LegalSection[] = [
  {
    heading: "Agreement to terms",
    blocks: [
      "These Terms of Service (\"Terms\") form a binding agreement between you (\"Customer\", \"you\") and Nxeon (\"we\", \"us\", \"our\") governing your access to and use of our virtual private server hosting, dashboard, APIs, and related services (collectively, the \"Services\").",
      "By creating an account, deploying a server, or otherwise using the Services, you agree to these Terms, our Privacy Policy, our Acceptable Use Policy, and our Service Level Agreement, each incorporated here by reference. If you do not agree, do not use the Services.",
    ],
  },
  {
    heading: "Accounts and eligibility",
    blocks: [
      "You must be at least 18 years old, or the age of majority in your jurisdiction, and able to form a binding contract to use the Services.",
      "You are responsible for the accuracy of your account information, for safeguarding your credentials, and for all activity that occurs under your account. Notify us immediately of any unauthorized use.",
      { list: [
        "One person or legal entity may not maintain more than one free-tier account except as expressly permitted.",
        "You may not share, resell, or transfer your account without our prior written consent.",
        "We may refuse, suspend, or terminate accounts at our discretion where required to protect the Services or comply with law.",
      ] },
    ],
  },
  {
    heading: "The Services",
    blocks: [
      "We provide on-demand virtual servers running on shared physical infrastructure, along with tools to deploy, manage, monitor, back up, and remove those servers. Specific resources (vCPU, memory, storage, bandwidth) are described on the applicable plan at the time of purchase.",
      "You are solely responsible for the configuration, security, content, and lawful operation of the software and data you run on your servers. We provide the underlying infrastructure; the operating system, applications, and data are yours to administer.",
    ],
  },
  {
    heading: "Fees, billing, and wallet",
    blocks: [
      "Paid Services are billed in advance from a prepaid wallet balance associated with your account. By adding funds and enabling a server, you authorize recurring monthly charges for that server until you cancel it.",
      { list: [
        "Prices are stated exclusive of any applicable taxes, which you are responsible for.",
        "Wallet top-ups are processed by our third-party payment providers; you agree to their terms as well.",
        "Servers with auto-renew enabled will renew automatically each billing period while your wallet has sufficient balance.",
        "If your balance is insufficient at renewal, affected servers may be suspended and, after a grace period, deleted.",
      ] },
      `${MONEY_BACK_TERMS} Beyond that, and except where required by law or expressly stated in our SLA, fees are non-refundable. Unused wallet balances may be refundable at our discretion following account verification.`,
    ],
  },
  {
    heading: "Acceptable use",
    blocks: [
      "Your use of the Services must comply with our Acceptable Use Policy at all times. Prohibited activity — including unlawful content, network abuse, and infringement of others' rights — may result in immediate suspension or termination without refund.",
    ],
  },
  {
    heading: "Customer content and backups",
    blocks: [
      "You retain all rights to the data and content you store on the Services. You grant us only the limited rights necessary to operate, maintain, back up, and provide the Services to you.",
      "While we offer automated snapshots and backups, you are responsible for maintaining your own independent backups of critical data. We are not liable for any loss of data.",
    ],
  },
  {
    heading: "Suspension and termination",
    blocks: [
      "We may suspend or terminate all or part of the Services, with or without notice, if you breach these Terms, create a security or legal risk, fail to pay, or engage in prohibited use.",
      "You may terminate at any time by deleting your servers and closing your account. Termination does not relieve you of fees accrued before termination.",
      "Upon termination, your servers and associated data may be permanently deleted. Export anything you need beforehand.",
    ],
  },
  {
    heading: "Warranties and disclaimers",
    blocks: [
/**
 * Nxeon's money-back guarantee (owner decision 2026-09-27, launched with the
 * new marketing site). The ONE source for every place that states it — the
 * Terms (lib/legal/terms.ts), the marketing reassurance card and comparison
 * pages (app/nxm/_data), and the support assistant's knowledge base
 * (lib/kb-system.ts) — so they can never disagree. Admins issue the refund
 * from the existing admin refund controls (components/admin/RefundControls).
 */
export const REFUND_WINDOW_HOURS = 72;
export const MONEY_BACK_LABEL = `${REFUND_WINDOW_HOURS}-hour money-back guarantee`;
/** What it covers, in one sentence (Terms, FAQs, the support assistant). */
export const MONEY_BACK_TERMS =
  `New customers can cancel their first order of a paid server or hosting plan within ${REFUND_WINDOW_HOURS} hours of purchase ` +
  "for a full refund of that order, requested from the dashboard or through support. Renewals, domain registrations and add-ons bought later are not covered.";

