/**
 * ORDER TRACKING DATA for a bare metal server (bm-ops side of the contract with
 * the wizard's lib/dedicated/tracking.ts, which turns this into steps, progress
 * and ETA wording).
 *
 * Everything here comes from OUR database: the DedicatedServer row, its latest
 * HANDOVER job (the OS install, polled by the worker) and the delivery history of
 * earlier orders. Nothing calls the supplier, so the tracking page can poll it
 * every 20-30 s for free. Customer-facing and BRAND-SAFE: the location is the
 * Nxeon customer label ("Canada (Montreal)"), never a supplier datacenter code, and
 * the raw availability code is reduced to an hour count.
 *
 * Pure helpers (etaHoursForStock, historicalEtaHours, buildTrackingData) are unit
 * tested in test/dedicated-tracking-data.test.ts; `loadTrackingData` is the DB loader.
 */
import { db } from "../db";
import { customerDedicatedRegionLabel, regionByCode } from "./regions";

export const TRACKING_DATA_VERSION = 1;

/** Delivery promise per availability code (hours until handover, our OS install included). */
export function etaHoursForStock(code: string | null | undefined): number {
  const m = /^(\d+)H/i.exec(code ?? "");
  if (!m) return 24;
  const h = Number(m[1]);
  if (h <= 1) return 2; // delivered within the hour upstream + our install and checks
  return h;
}

/** Minimum delivered orders before history overrides the availability promise. */
export const HISTORY_MIN_SAMPLES = 5;

/**
 * Median order-to-delivery hours from earlier deliveries: same availability code
 * first, then all codes, else null (not enough data yet).
 */
export function historicalEtaHours(history: { stockAtOrder: string | null; hours: number }[], code: string | null | undefined): number | null {
  const median = (xs: number[]) => {
    const s = [...xs].sort((a, b) => a - b);
    const mid = Math.floor(s.length / 2);
    return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
  };
  const ok = history.filter((h) => Number.isFinite(h.hours) && h.hours >= 0 && h.hours < 24 * 60);
  const bucket = (c: string | null | undefined) => (/^(\d+)H/i.exec(c ?? "")?.[1] ?? "?");
  const same = ok.filter((h) => bucket(h.stockAtOrder) === bucket(code));
  if (same.length >= HISTORY_MIN_SAMPLES) return Math.max(1, Math.round(median(same.map((h) => h.hours)) * 10) / 10);
  if (ok.length >= HISTORY_MIN_SAMPLES) return Math.max(1, Math.round(median(ok.map((h) => h.hours)) * 10) / 10);
  return null;
}

/** The install job as cached in our DB (worker-updated). */
export type TrackingJob = { status: string; step: string; progress: number; updatedAt: string; error: string | null };

export type TrackingData = {
  version: number;
  serverId: string;
  /** DedicatedServer.status: PENDING | PROVISIONING | ACTIVE | SUSPENDED | CANCELLED */
  status: string;
  /** Where the build is, in order: paid -> sourcing -> installing -> ready (or ended). */
  stage: "paid" | "sourcing" | "installing" | "ready" | "ended";
  orderedAt: string;
  /** Payment confirmed (orders are only created once paid, so = orderedAt). */
  paidAt: string;
  provisionedAt: string | null;
  /** Customer-facing location label and ISO2 country for the flag. */
  location: string;
  country: string;
  /** Expected handover, and how it was estimated. */
  etaHours: number;
  expectedBy: string;
  etaSource: "history" | "availability";
  /** True once now is past expectedBy and the server is not ready. */
  late: boolean;
  /** Latest OS install/handover job, from our DB (null before it starts). */
  install: TrackingJob | null;
  /** The machine has been assigned to this order (staff linked it, or it was delivered). */
  machineAssigned: boolean;
  credentialsReady: boolean;
  ipv4: string | null;
  /** When this record last changed (for "Last updated"). */
  updatedAt: string;
};

type Row = {
  id: string;
  status: string;
  createdAt: Date;
  updatedAt: Date;
  provisionedAt: Date | null;
  region: string;
  stockAtOrder?: string | null;
  providerServiceName: string | null;
  credentialsDeliveredAt: Date | null;
  ipv4: string[];
};

/** Pure: tracking data from our own row, its latest install job and delivery history. */
export function buildTrackingData(s: Row, job: { status: string; step: string; progress: number; updatedAt: Date; error: string | null } | null, history: { stockAtOrder: string | null; hours: number }[], now: Date): TrackingData {
  const hist = historicalEtaHours(history, s.stockAtOrder ?? null);
  const etaHours = hist ?? etaHoursForStock(s.stockAtOrder ?? null);
  const expectedBy = new Date(s.createdAt.getTime() + etaHours * 3_600_000);
  const ready = s.status === "ACTIVE" || s.status === "SUSPENDED";
  const installing = !!job && (job.status === "QUEUED" || job.status === "RUNNING" || job.status === "WAITING");
  const stage: TrackingData["stage"] =
    s.status === "CANCELLED" ? "ended"
    : ready ? "ready"
    : installing ? "installing"
    : s.status === "PROVISIONING" || !!s.providerServiceName ? "sourcing"
    : "paid";
  const lastChange = Math.max(s.updatedAt.getTime(), job?.updatedAt.getTime() ?? 0);
  return {
    version: TRACKING_DATA_VERSION,
    serverId: s.id,
    status: s.status,
    stage,
    orderedAt: s.createdAt.toISOString(),
    paidAt: s.createdAt.toISOString(),
    provisionedAt: s.provisionedAt?.toISOString() ?? null,
    location: customerDedicatedRegionLabel(s.region),
    country: regionByCode(s.region)?.country ?? "",
    etaHours,
    expectedBy: expectedBy.toISOString(),
    etaSource: hist != null ? "history" : "availability",
    late: !ready && s.status !== "CANCELLED" && now.getTime() > expectedBy.getTime(),
    install: job ? { status: job.status, step: job.step, progress: job.progress, updatedAt: job.updatedAt.toISOString(), error: job.status === "FAILED" ? "Our engineers are finishing this by hand." : null } : null,
    machineAssigned: !!s.providerServiceName || ready,
    credentialsReady: !!s.credentialsDeliveredAt || ready,
    ipv4: ready ? s.ipv4[0] ?? null : null,
    updatedAt: new Date(lastChange).toISOString(),
  };
}

/** Delivery history: recent online orders that reached ACTIVE (hours from order to delivery). */
export async function deliveryHistory(limit = 200): Promise<{ stockAtOrder: string | null; hours: number }[]> {
  const rows = await db.dedicatedServer.findMany({
    where: { provisionedAt: { not: null }, orderKey: { not: null } },
    orderBy: { provisionedAt: "desc" },
    take: limit,
    select: { createdAt: true, provisionedAt: true, stockAtOrder: true },
  });
  return rows.map((r) => ({ stockAtOrder: r.stockAtOrder, hours: (r.provisionedAt!.getTime() - r.createdAt.getTime()) / 3_600_000 }));
}

/** DB loader. `userId` null = admin/preview (no owner check). */
export async function loadTrackingData(serverId: string, userId: string | null, now = new Date()): Promise<TrackingData | null> {
  const s = await db.dedicatedServer.findUnique({ where: { id: serverId } });
  if (!s || (userId !== null && s.userId !== userId)) return null;
  const [job, history] = await Promise.all([
    db.dedicatedJob.findFirst({ where: { dedicatedServerId: s.id, kind: "HANDOVER" }, orderBy: { createdAt: "desc" }, select: { status: true, step: true, progress: true, updatedAt: true, error: true } }),
    deliveryHistory(),
  ]);
  return buildTrackingData(s, job, history, now);
}

