/**
 * ADMIN-ONLY operational health for bare metal: the orders queue with stuck-order
 * alerts, failed/stuck jobs, IP orders waiting for approval, renewals, catalogue
 * sync freshness and the mode flags. Read by /admin/dedicated/ops and by the
 * worker's stuck-order alert (worker/dedicated-billing.ts dedicatedOpsAlerts).
 * `classifyOrder` / `syncHealth` are pure (test/dedicated-ops-health.test.ts).
 */
import { db } from "../db";
import { getSetting, getSettingBool, getSettingInt } from "../settings";
import { DEDICATED_OVH_MOCK } from "./ovh-mock";
import { etaHoursForStock } from "./tracking-data";

const H = 3_600_000;

export type OrderAlert = "ok" | "due-soon" | "late" | "very-late";

/** Where an undelivered order stands against its promise (ETA from the availability code at order time). */
export function classifyOrder(o: { status: string; createdAt: Date; stockAtOrder: string | null }, now: Date): { alert: OrderAlert; ageHours: number; etaHours: number } {
  const ageHours = (now.getTime() - o.createdAt.getTime()) / H;
  const etaHours = etaHoursForStock(o.stockAtOrder);
  if (o.status !== "PENDING" && o.status !== "PROVISIONING") return { alert: "ok", ageHours, etaHours };
  const alert: OrderAlert = ageHours > etaHours * 2 ? "very-late" : ageHours > etaHours ? "late" : ageHours > etaHours * 0.75 ? "due-soon" : "ok";
  return { alert, ageHours, etaHours };
}

export type SyncHealth = { status: "ok" | "stale" | "failing" | "never"; ageHours: number | null; lastStatus: string | null; lastError: string | null };

export function syncHealth(last: { status: string; startedAt: Date; error: string | null } | null, lastOk: { startedAt: Date } | null, intervalHours: number, now: Date): SyncHealth {
  if (!last) return { status: "never", ageHours: null, lastStatus: null, lastError: null };
  const ageHours = lastOk ? (now.getTime() - lastOk.startedAt.getTime()) / H : null;
