import Link from "next/link";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { PageHeader, Badge, EmptyState } from "@/components/ui/primitives";
import { RetryJobButton, IpOrderButtons } from "@/components/admin/dedicated/OpsControls";
import { loadDedicatedOps } from "@/lib/dedicated/ops-health";
import { money } from "@/lib/dedicated/pricing";

export const dynamic = "force-dynamic";

const ts = (d: Date | null | undefined) => (d ? d.toISOString().slice(0, 16).replace("T", " ") : "—");
const ALERT_TONE = { ok: "green", "due-soon": "amber", late: "red", "very-late": "red" } as const;
const SYNC_TONE = { ok: "green", stale: "amber", failing: "red", never: "slate" } as const;

/**
 * ADMIN-ONLY bare metal operations: health flags, the orders queue with
 * stuck-order alerts, failed/stuck jobs (retry), IP orders waiting, renewals,
 * corrections and the audit trail. Names the supplier freely (admin only).
 */
export default async function AdminDedicatedOps() {
  await requireAdmin();
  const o = await loadDedicatedOps().catch(() => null);
  if (!o) return <div className="space-y-6"><PageHeader title="Bare metal operations" /><EmptyState title="Tables not migrated" sub="Run prisma db push on this database first." /></div>;
  const userIds = [...new Set([...o.orders.map((r) => r.userId), ...o.renewFailed.map((r) => r.userId), ...o.renewSoon.map((r) => r.userId)])];
  const emails = new Map((await db.user.findMany({ where: { id: { in: userIds } }, select: { id: true, email: true } })).map((u) => [u.id, u.email]));
  const late = o.orders.filter((r) => r.alert === "late" || r.alert === "very-late").length;
  const issues = late + o.jobsStuck.length + o.jobsFailed.length + o.ipPending.length + o.renewFailed.length + (o.sync.status === "ok" ? 0 : 1);

  return (
    <div className="space-y-6">
      <PageHeader title="Bare metal operations" sub={`${o.orders.length} undelivered orders · ${issues} things need attention`}>
        <Link href="/admin/dedicated/servers" className="btn-ghost py-1.5 text-xs">Managed servers</Link>
        <Link href="/admin/dedicated" className="btn-ghost py-1.5 text-xs">Catalogue</Link>
        <Link href="/admin/dedicated/pricing" className="btn-ghost py-1.5 text-xs">Pricing</Link>
      </PageHeader>

      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        <div className="card space-y-1 p-4 text-xs"><div className="text-slate-500">Catalogue sync (OVH public feeds)</div><div className="flex items-center gap-2"><Badge tone={SYNC_TONE[o.sync.status]}>{o.sync.status.toUpperCase()}</Badge><span>{o.sync.ageHours != null ? `last good ${o.sync.ageHours.toFixed(1)} h ago` : "no good sync yet"}</span></div><div className="text-slate-500">every {o.syncHours} h{o.sync.lastError ? ` · ${o.sync.lastError.slice(0, 80)}` : ""}</div></div>
        <div className="card space-y-1 p-4 text-xs"><div className="text-slate-500">Upstream mode</div><div className="flex flex-wrap gap-1.5">{o.flags.mock ? <Badge tone="brand">MOCK</Badge> : null}<Badge tone={o.flags.dryRun ? "amber" : "green"}>{o.flags.dryRun ? "DRY RUN" : "LIVE WRITES"}</Badge><Badge tone={o.flags.upstreamReadable ? "green" : "red"}>{o.flags.upstreamReadable ? "reads configured" : "no read access"}</Badge></div><div className="text-slate-500">{o.flags.protectedServices} extra protected service names</div></div>
        <div className="card space-y-1 p-4 text-xs"><div className="text-slate-500">Billing</div><div className="flex flex-wrap gap-1.5"><Badge tone={o.flags.autoRenew ? "green" : "amber"}>{o.flags.autoRenew ? "AUTO-PAY ON" : "AUTO-PAY OFF"}</Badge><Badge tone="slate">no refunds · no discounts</Badge></div><div className="text-slate-500">{o.overdueRenewals} past renewal date · {o.renewFailed.length} failed · {o.suspendedUnpaid.length} suspended unpaid</div></div>
        <div className="card space-y-1 p-4 text-xs"><div className="text-slate-500">Public release</div><div><Badge tone={o.flags.publicOn ? "green" : "slate"}>{o.flags.publicOn ? "PUBLIC" : "PRIVATE PREVIEW"}</Badge></div><div className="text-slate-500">See the release checklist before switching it on.</div></div>
      </div>

      <div className="card p-0">
        <h3 className="px-5 pt-4 text-sm font-semibold">Orders queue (paid, not delivered)</h3>
        {o.orders.length === 0 ? <p className="px-5 pb-4 pt-2 text-xs text-slate-400">Nothing waiting.</p> : (
          <div className="overflow-x-auto">
            <table className="mt-2 w-full min-w-[820px] text-left text-xs">
              <thead className="border-b border-white/[0.06] text-[11px] uppercase tracking-wider text-slate-500"><tr><th className="px-3 py-2">Server</th><th className="px-3 py-2">Customer</th><th className="px-3 py-2">State</th><th className="px-3 py-2">Ordered</th><th className="px-3 py-2">Age / promise</th><th className="px-3 py-2">Stock at order</th><th className="px-3 py-2">Upstream</th></tr></thead>
              <tbody className="divide-y divide-white/[0.04]">
                {o.orders.map((r) => (
                  <tr key={r.id}>
                    <td className="px-3 py-2"><Link className="font-semibold hover:underline" href={`/admin/dedicated/servers/${r.id}`}>{r.label}</Link></td>
                    <td className="px-3 py-2 text-slate-300">{emails.get(r.userId) ?? r.userId}</td>
                    <td className="px-3 py-2"><Badge tone={r.status === "PENDING" ? "slate" : "brand"}>{r.status}</Badge></td>
                    <td className="px-3 py-2 text-slate-400">{ts(r.createdAt)}</td>
                    <td className="px-3 py-2"><Badge tone={ALERT_TONE[r.alert]}>{r.alert === "ok" ? "on time" : r.alert}</Badge> <span className="text-slate-400">{Math.round(r.ageHours)} h / {r.etaHours} h</span></td>
                    <td className="px-3 py-2 font-mono text-slate-400">{r.stockAtOrder ?? "—"}</td>
                    <td className="px-3 py-2 font-mono text-[10px] text-slate-500">{r.providerServiceName ?? "not linked"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <div className="grid gap-4 lg:grid-cols-2">
        <div className="card space-y-2 p-5">
          <h3 className="text-sm font-semibold">Stuck jobs</h3>
          {o.jobsStuck.length === 0 ? <p className="text-xs text-slate-400">None.</p> : (
            <ul className="divide-y divide-white/[0.04] text-xs">{o.jobsStuck.map((j) => <li key={j.id} className="flex flex-wrap gap-2 py-1.5"><Badge tone="amber">{j.status}</Badge><b>{j.kind}</b><Link className="underline" href={`/admin/dedicated/servers/${j.server.id}`}>{j.server.label}</Link><span className="text-slate-400">{j.step}</span><span className="text-slate-500">updated {ts(j.updatedAt)}</span></li>)}</ul>
          )}
          <h3 className="pt-2 text-sm font-semibold">Failed jobs (7 days)</h3>
          {o.jobsFailed.length === 0 ? <p className="text-xs text-slate-400">None.</p> : (
            <ul className="divide-y divide-white/[0.04] text-xs">{o.jobsFailed.map((j) => <li key={j.id} className="flex flex-wrap items-center gap-2 py-1.5"><Badge tone="red">FAILED</Badge><b>{j.kind}</b><Link className="underline" href={`/admin/dedicated/servers/${j.server.id}`}>{j.server.label}</Link><span className="text-slate-300">{j.error ?? j.step}</span><span className="text-slate-500">{ts(j.finishedAt)}</span>{j.kind !== "HANDOVER" && <RetryJobButton jobId={j.id} label={j.server.label} />}</li>)}</ul>
          )}
        </div>
        <div className="card space-y-2 p-5">
          <h3 className="text-sm font-semibold">Extra-IP orders waiting</h3>
          {o.ipPending.length === 0 ? <p className="text-xs text-slate-400">None.</p> : (
            <ul className="divide-y divide-white/[0.04] text-xs">{o.ipPending.map((x) => <li key={x.id} className="flex flex-wrap items-center gap-2 py-1.5"><Badge tone={x.status === "PAID" ? "amber" : "red"}>{x.status}</Badge><Link className="underline" href={`/admin/dedicated/servers/${x.server.id}`}>{x.server.label}</Link><span>{x.quantity} IP · {money(x.chargedCents)}</span><span className="text-slate-500">{ts(x.createdAt)}</span><IpOrderButtons orderId={x.id} status={x.status} /></li>)}</ul>
          )}
        </div>
      </div>

      <div className="grid gap-4 lg:grid-cols-2">
        <div className="card space-y-2 p-5">
          <h3 className="text-sm font-semibold">Renewals needing attention</h3>
          {o.renewFailed.length + o.suspendedUnpaid.length + o.cancelling.length === 0 ? <p className="text-xs text-slate-400">None.</p> : (
            <ul className="divide-y divide-white/[0.04] text-xs">
              {o.renewFailed.map((r) => <li key={`f${r.id}`} className="flex flex-wrap gap-2 py-1.5"><Badge tone="red">FAILED</Badge><Link className="underline" href={`/admin/dedicated/servers/${r.id}`}>{r.label}</Link><span>{emails.get(r.userId) ?? ""}</span><span className="text-slate-400">due {r.renewalDate?.toISOString().slice(0, 10)} · failed {ts(r.renewalFailedAt)}</span></li>)}
              {o.suspendedUnpaid.map((r) => <li key={`s${r.id}`} className="flex flex-wrap gap-2 py-1.5"><Badge tone="amber">SUSPENDED</Badge><Link className="underline" href={`/admin/dedicated/servers/${r.id}`}>{r.label}</Link><span className="text-slate-400">{r.suspendReason}</span></li>)}
              {o.cancelling.map((r) => <li key={`c${r.id}`} className="flex flex-wrap gap-2 py-1.5"><Badge tone="slate">ENDS</Badge><Link className="underline" href={`/admin/dedicated/servers/${r.id}`}>{r.label}</Link><span className="text-slate-400">cancelled by customer; ends {r.renewalDate?.toISOString().slice(0, 10)}</span></li>)}
            </ul>
          )}
          <h3 className="pt-2 text-sm font-semibold">Renewing in the next 14 days</h3>
          {o.renewSoon.length === 0 ? <p className="text-xs text-slate-400">None.</p> : (
            <ul className="divide-y divide-white/[0.04] text-xs">{o.renewSoon.map((r) => <li key={r.id} className="flex flex-wrap gap-2 py-1.5"><span className="font-mono text-slate-400">{r.renewalDate?.toISOString().slice(0, 10)}</span><Link className="underline" href={`/admin/dedicated/servers/${r.id}`}>{r.label}</Link><span className="font-mono">{r.renewalMonthlyCents != null ? money(r.renewalMonthlyCents * r.termMonths) : "—"}</span><span className="text-slate-500">{emails.get(r.userId) ?? ""}</span></li>)}</ul>
          )}
        </div>
        <div className="card space-y-2 p-5">
          <h3 className="text-sm font-semibold">Billing corrections (latest)</h3>
          {o.corrections.length === 0 ? <p className="text-xs text-slate-400">None.</p> : (
            <ul className="divide-y divide-white/[0.04] text-xs">{o.corrections.map((c) => <li key={c.id} className="flex flex-wrap gap-2 py-1.5"><span className="font-mono text-slate-500">{ts(c.createdAt)}</span><b>{c.kind}</b><span className="font-mono">{money(c.amountCents)}</span><Link className="underline" href={`/admin/dedicated/servers/${c.dedicatedServerId}`}>server</Link><span className="text-slate-300">{c.reason}</span></li>)}</ul>
          )}
        </div>
      </div>

      <div className="card space-y-2 p-5">
        <h3 className="text-sm font-semibold">Audit trail (all bare metal servers)</h3>
        <ul className="divide-y divide-white/[0.04] text-xs">
          {o.events.map((e) => (
            <li key={e.id} className="flex flex-wrap gap-3 py-1.5">
              <span className="font-mono text-slate-500">{ts(e.createdAt)}</span>
              <Link className="underline" href={`/admin/dedicated/servers/${e.server.id}`}>{e.server.label}</Link>
              <b>{e.action}</b>
              {e.detail && <span className="text-slate-300">{e.detail.slice(0, 200)}</span>}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

