/**
 * Stuck-order alerts (runs every sweep, whether or not auto-pay is on): every
 * ADMIN gets one notification per server per 12 h when a paid order is past its
 * delivery promise, and when a renewal date passed while auto-pay is off.
 */
export async function dedicatedOpsAlerts(deps: Pick<BillingDeps, "now" | "notifyAdmins"> = defaultBillingDeps(), autoRenew = false): Promise<number> {
  const { classifyOrder } = await import("../lib/dedicated/ops-health");
  const now = deps.now();
  const since = new Date(now.getTime() - 12 * 3_600_000);
  let n = 0;
  const open = await db.dedicatedServer.findMany({ where: { status: { in: ["PENDING", "PROVISIONING"] } }, select: { id: true, label: true, status: true, createdAt: true, stockAtOrder: true } });
  const overdue = autoRenew ? [] : await db.dedicatedServer.findMany({ where: { status: "ACTIVE", cancelAtPeriodEnd: false, renewalDate: { lt: now } }, select: { id: true, label: true, renewalDate: true } });
  const recent = new Set((await db.dedicatedServerEvent.findMany({ where: { action: { in: ["late_order_alert", "overdue_renewal_alert"] }, createdAt: { gt: since } }, select: { dedicatedServerId: true, action: true } })).map((e) => `${e.action}:${e.dedicatedServerId}`));
  for (const s of open) {
    const c = classifyOrder(s, now);
    if ((c.alert !== "late" && c.alert !== "very-late") || recent.has(`late_order_alert:${s.id}`)) continue;
    await db.dedicatedServerEvent.create({ data: { dedicatedServerId: s.id, action: "late_order_alert", detail: `${Math.round(c.ageHours)} h old, promise ${c.etaHours} h` } });
    await deps.notifyAdmins(`Late bare metal order: ${s.label}`, `Paid ${Math.round(c.ageHours)} h ago, promised in about ${c.etaHours} h. Status ${s.status}.`, adminHref(s.id));
    n++;
  }
  for (const s of overdue) {
    if (recent.has(`overdue_renewal_alert:${s.id}`)) continue;
    await db.dedicatedServerEvent.create({ data: { dedicatedServerId: s.id, action: "overdue_renewal_alert", detail: `renewal date ${ymd(s.renewalDate!)} passed; auto-pay is off` } });
    await deps.notifyAdmins(`Bare metal renewal overdue: ${s.label}`, `Renewal date ${ymd(s.renewalDate!)} passed and auto-pay is off. Renew by hand or turn on dedicated_autorenew_enabled.`, adminHref(s.id));
    n++;
  }
  return n;
}
EOF
