import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import { isPromoDescription, spendableRealFunds, PROMO_DESCRIPTION_PREFIXES } from "../lib/wallet-funds.ts";
import { renewalAction, renewalNetCents, renewalTaxCents, nextRenewalDate, isUnpaidSuspension, UNPAID_SUSPEND_REASON, type RenewalRow } from "../lib/dedicated/billing-core.ts";
import { etaHoursForStock, historicalEtaHours, buildTrackingData } from "../lib/dedicated/tracking-data.ts";
import { classifyOrder, syncHealth } from "../lib/dedicated/ops-health.ts";
import { correctionCap, isDedicatedInvoiceDescription } from "../lib/dedicated/billing-correction.ts";
import { liveCacheView, LIVE_STALE_MS } from "../lib/dedicated/live-cache.ts";
import { parseDedicatedIntent } from "../lib/dedicated/order-core.ts";
import { sellMonthlyCents, type PricingRules } from "../lib/dedicated/pricing.ts";
import { validateOfferInput } from "../lib/offer-pricing.ts";
import { isCommissionableInvoice } from "../lib/partner-commission.ts";

/**
 * Bare metal release hardening (bm-ops, 2026-10-08): the pure rules behind
 * real-funds-only payment, auto-pay renewals, no refunds / no discounts,
 * tracking ETAs, ops alerts and the live cache. DB paths: test/dedicated-ops-db.test.ts.
 */
const ROOT = path.resolve(__dirname, "..");
const read = (p: string) => readFileSync(path.join(ROOT, p), "utf8");
const DAY = 86_400_000;

/* ---------------- real funds only ---------------- */

test("real funds: promotional credit is held back, never spendable on bare metal", () => {
  assert.deepEqual(spendableRealFunds(10_000, 0), { spendableCents: 10_000, heldCreditCents: 0 }, "real funds only");
  assert.deepEqual(spendableRealFunds(500, 500), { spendableCents: 0, heldCreditCents: 500 }, "credit only");
  assert.deepEqual(spendableRealFunds(12_500, 2_500), { spendableCents: 10_000, heldCreditCents: 2_500 }, "mixed wallet");
  assert.deepEqual(spendableRealFunds(1_000, 5_000), { spendableCents: 0, heldCreditCents: 1_000 }, "credit larger than balance (spent elsewhere) holds the whole balance");
  assert.deepEqual(spendableRealFunds(-50, 0), { spendableCents: 0, heldCreditCents: 0 });
});

test("legacy (untagged) promotional rows are recognised by description", () => {
  for (const d of ["Welcome credit", "Referral bonus — welcome reward", "Referral bonus — you referred a friend", "Promo NXSAVE — 10% bonus", "Promo code redeemed (FREE5)", "Riddle prize — $100 credit (valid toward one VPS)", "Gift code redeemed (ABC)", "Admin credit adjustment", "Admin balance adjustment — goodwill", "Sandbox credit (test funds)"]) {
    assert.equal(isPromoDescription(d), true, d);
  }
  for (const d of ["Stripe payment (cs_test_1)", "PayPal payment (x)", "Card payment for renewal", "Billing correction — box: double charge", "Refund: failed registration a.com"]) {
    assert.equal(isPromoDescription(d), false, d);
  }
});

test("every promotional credit grant site tags its ledger row PROMO (no grant can slip into real funds)", () => {
  const sites: [string, RegExp][] = [
    ["lib/actions.ts", /description: "Welcome credit", fundsKind: "PROMO"/],
    ["lib/actions.ts", /description: `Promo \$\{couponCode!\.toUpperCase\(\)\} — \$\{couponLabel\}`,\s*fundsKind: "PROMO"/],
    ["lib/actions.ts", /description: `Admin credit adjustment`, fundsKind: cents > 0 \? "PROMO" : null/],
    ["lib/discord-auth.ts", /description: "Welcome credit", fundsKind: "PROMO"/],
    ["app/api/auth/google/callback/route.ts", /description: "Welcome credit", fundsKind: "PROMO"/],
    ["lib/riddle.ts", /description: RIDDLE_PRIZE_DESC, fundsKind: "PROMO"/],
    ["lib/actions-growth.ts", /"Referral bonus — welcome reward", fundsKind: "PROMO"/],
    ["lib/actions-growth.ts", /"Referral bonus — you referred a friend",\s*fundsKind: "PROMO"/],
    ["lib/actions-gift.ts", /`Gift code redeemed \(\$\{gift\.code\}\)`,\s*fundsKind: "PROMO"/],
    ["lib/actions-gift.ts", /`Promo code redeemed \(\$\{coupon\.code\}\)`, fundsKind: "PROMO"/],
    ["lib/actions-admin-billing.ts", /amountCents: cents, description, fundsKind: cents > 0 \? "PROMO" : null/],
    ["lib/actions-sandbox.ts", /"Sandbox credit \(test funds\)", fundsKind: "PROMO"/],
  ];
  for (const [f, re] of sites) assert.match(read(f), re, `${f} must tag its promotional credit row`);
  // and each tagged prefix is also in the legacy list (old rows written before the tag)
  for (const p of ["Welcome credit", "Referral bonus", "Promo ", "Riddle prize", "Gift code redeemed", "Admin credit adjustment", "Admin balance adjustment", "Sandbox credit"]) {
    assert.ok((PROMO_DESCRIPTION_PREFIXES as readonly string[]).includes(p), p);
  }
});

test("dedicated money paths debit REAL funds only (never the plain wallet debit)", () => {
  for (const f of ["lib/dedicated/order.ts", "lib/dedicated/ip-order.ts", "worker/dedicated-billing.ts"]) {
    const src = read(f);
    assert.match(src, /debitRealFunds\(/, `${f} uses debitRealFunds`);
    assert.doesNotMatch(src, /\bdebitWallet\(/, `${f} must not use debitWallet`);
  }
  for (const f of ["lib/actions-dedicated-order.ts", "lib/actions-dedicated-ops.ts", "app/dashboard/dedicated/page.tsx", "app/dashboard/dedicated/[id]/page.tsx"]) {
    const src = read(f);
    assert.match(src, /dedicatedSpendable\(/, `${f} splits on spendable real funds`);
    assert.doesNotMatch(src, /balanceCents: user\.balanceCents|balanceCents=\{user\.balanceCents\}/, `${f} must not offer the raw balance`);
  }
});

/* ---------------- non-refundable acknowledgement ---------------- */

test("order intent: acceptedNoRefund is parsed strictly (only literal true)", () => {
  const base = { itemId: "cmabcdefgh12", region: "sgp1", os: "ubuntu-2404", termMonths: 1, memoryId: null, storageId: null, bandwidthId: null, label: "x", orderKey: "k".repeat(16) };
  assert.equal(parseDedicatedIntent({ ...base, acceptedNoRefund: true })?.acceptedNoRefund, true);
  assert.equal(parseDedicatedIntent({ ...base, acceptedNoRefund: "true" })?.acceptedNoRefund, false);
  assert.equal(parseDedicatedIntent(base)?.acceptedNoRefund, false);
  assert.match(read("lib/actions-dedicated-order.ts"), /if \(!intent\.acceptedNoRefund\) return \{ ok: false, error: NO_REFUND_ACK_REQUIRED \}/);
  assert.match(read("lib/dedicated/order.ts"), /if \(!intent\.acceptedNoRefund && opts\.via === "wallet"\) throw new DedicatedOrderError\(NO_REFUND_ACK_REQUIRED\)/);
  assert.match(read("lib/dedicated/order.ts"), /acceptedNoRefundAt: intent\.acceptedNoRefund \? now : null/);
});

/* ---------------- no discounts ---------------- */

const RULES: PricingRules = { markupPercent: -50, markupFixedCents: 0, upliftPercent: 0, rounding: "none", setupPolicy: "pass", setupCustomCents: 0 } as PricingRules;

test("no discounts: the bare metal price never drops below cost, whatever markup or override", () => {
  assert.equal(sellMonthlyCents(10_000, RULES), 10_000, "negative markup floored at cost");
  assert.equal(sellMonthlyCents(10_000, { ...RULES, markupPercent: 25 }), 12_500);
  assert.equal(sellMonthlyCents(10_000, { ...RULES, markupPercent: 25 }, { overrideMonthlyCents: 5_000 }), 10_000, "override below cost floored");
  assert.equal(sellMonthlyCents(10_000, { ...RULES, markupPercent: 25 }, { overrideMonthlyCents: 15_000 }), 15_000);
});

test("no discounts: a DEDICATED custom offer can't carry a discount or a cheaper first term", () => {
  const base = { kind: "DEDICATED", title: "Big box", cpuCores: 16, ramMB: 65536, diskGB: 2000, storageTier: "nvme", bandwidthTB: 10, termMonths: 1, renewalMonthlyCents: 20_000, firstTermCents: 20_000, setupFeeCents: 0, expiresInDays: 7, discountPercent: null, discountLabel: "", notes: "", internalNote: "", hostname: "" } as never as Parameters<typeof validateOfferInput>[0];
  assert.deepEqual(validateOfferInput(base), []);
  assert.ok(validateOfferInput({ ...base, firstTermCents: 10_000 }).some((e) => /can't be discounted/.test(e)));
  assert.ok(validateOfferInput({ ...base, discountPercent: 20 }).some((e) => /can't be discounted/.test(e)));
  assert.ok(!validateOfferInput({ ...base, kind: "VPS", cpuCores: 2, ramMB: 4096, diskGB: 80, firstTermCents: 10_000 } as never).some((e) => /can't be discounted/.test(e)), "VPS offers keep their discounts");
});

test("no partner commission accrues on bare metal invoices (order, renewal, extra IPs)", () => {
  const inv = (description: string) => ({ id: "i", userId: "u", status: "PAID", amountCents: 10_000, taxCents: 0, description, createdAt: new Date(), dedicatedIpCents: 0 }) as never;
  assert.equal(isCommissionableInvoice(inv("Bare Metal Dedicated Server — NX-Forge 8-64 · Canada")), false);
  assert.equal(isCommissionableInvoice(inv("Bare Metal Dedicated Server renewal — box")), false);
  assert.equal(isCommissionableInvoice(inv("Bare Metal Dedicated Server extra IPs — box")), false);
  assert.equal(isCommissionableInvoice(inv("VPS Starter — web-01")), true);
});

test("no coupon, promo or discount machinery is reachable from the dedicated checkout code", () => {
  const files = ["lib/dedicated/order.ts", "lib/dedicated/order-core.ts", "lib/dedicated/ip-order.ts", "lib/actions-dedicated-order.ts", "worker/dedicated-billing.ts"];
  for (const f of files) {
    const src = read(f).replace(/\/\*[\s\S]*?\*\/|\/\/.*$/gm, "");
    assert.doesNotMatch(src, /coupon|promoRedemption|partnerDiscount|introFirstTerm|annualDiscount|termDiscountPct|grandfather|retentionDiscount|firstMonthFree/i, `${f} must not touch a discount mechanism`);
  }
  const stripe = read("lib/stripe.ts");
  const ded = stripe.slice(stripe.indexOf("export async function createDedicatedOrderPaymentSession"), stripe.indexOf("export async function createGameOrderPaymentSession"));
  assert.ok(ded.length > 100);
  assert.doesNotMatch(ded, /allow_promotion_codes|discounts\s*:/, "dedicated Stripe sessions accept no promotion codes");
});

/* ---------------- no refunds ---------------- */

test("no refunds: admin refund tool refuses dedicated invoices and dedicated card legs", () => {
  const src = read("lib/actions-admin-billing.ts");
  assert.match(src, /if \(await isDedicatedInvoice\(invoice\)\) return \{ error: DEDICATED_NO_REFUND_ADMIN \}/);
  assert.match(src, /leg\.kind === "dedicatedOrder" \|\| leg\.kind === "dedicatedIpOrder"\) && leg\.status !== "FAILED"/);
  assert.equal(isDedicatedInvoiceDescription("Bare Metal Dedicated Server — x"), true);
  assert.equal(isDedicatedInvoiceDescription("Bare Metal Dedicated Server renewal — x"), true);
  assert.equal(isDedicatedInvoiceDescription("VPS — x"), false);
  // the old IP "Reject & refund" is gone; non-delivery goes through the audited correction
  const ip = read("lib/dedicated/ip-order.ts");
  assert.doesNotMatch(ip, /Refund: extra IPs/);
  assert.match(ip, /applyBillingCorrection\(\{[^}]*kind: "NOT_DELIVERED"/);
  assert.equal(correctionCap(10_000, 2_500), 7_500);
  assert.equal(correctionCap(1_000, 5_000), 0);
});

test("no money-back / guarantee / refund promise on any customer bare metal surface", () => {
  const roots = ["components/dedicated", "app/dashboard/dedicated", "app/(marketing)/dedicated-servers", "tools/nxm/native/dedicated-servers"];
  const files: string[] = [];
  const walk = (d: string) => { for (const f of readdirSync(path.join(ROOT, d))) { const p = path.join(d, f); if (statSync(path.join(ROOT, p)).isDirectory()) walk(p); else if (/\.(tsx?|html|js|json)$/.test(f)) files.push(p); } };
  roots.forEach(walk);
  assert.ok(files.length > 5);
  for (const f of files) {
    const src = read(f);
    assert.doesNotMatch(src, /MoneyBackNote|money-back|moneyback|30-day|72-hour|guarantee/i, `${f}`);
    assert.doesNotMatch(src.replace(/non-refundable|isn't refunded|is refunded or prorated|Nothing is refunded|nothing is refunded|no refund|No refund|not refunded/gi, ""), /\brefund(ed)?\b/i, `${f} must not promise a refund`);
  }
});

test("cancellation runs to the end of the paid period (no immediate stop, no proration)", () => {
  const src = read("lib/actions-dedicated-customer.ts");
  assert.match(src, /cancelAtPeriodEnd: true, cancelRequestedAt: new Date\(\)/);
  assert.doesNotMatch(src, /status: "CANCELLED"/);
});

/* ---------------- auto-pay renewals ---------------- */

const due = new Date("2026-11-01T00:00:00Z");
const row = (over: Partial<RenewalRow> = {}): RenewalRow => ({ status: "ACTIVE", renewalDate: due, renewalMonthlyCents: 18_999, termMonths: 1, cancelAtPeriodEnd: false, renewalLastAttemptAt: null, renewalWarnedFor: null, suspendReason: null, ...over });
const cfg = { graceDays: 3, terminateDays: 10 };
const at = (days: number) => new Date(due.getTime() + days * DAY);

test("renewal policy: warn T-3d once, charge at T, retry daily, suspend after grace, end after terminate days", () => {
  assert.equal(renewalAction(row(), at(-5), cfg).kind, "none");
  assert.equal(renewalAction(row(), at(-2), cfg).kind, "warn");
  assert.equal(renewalAction(row({ renewalWarnedFor: due }), at(-2), cfg).kind, "none", "warned once per period");
  assert.equal(renewalAction(row(), at(0), cfg).kind, "charge");
  assert.equal(renewalAction(row({ renewalLastAttemptAt: at(0.1) }), at(0.5), cfg).kind, "none", "no retry within ~20h");
  assert.equal(renewalAction(row({ renewalLastAttemptAt: at(0.1) }), at(1.1), cfg).kind, "charge", "daily retry");
  assert.equal(renewalAction(row({ renewalLastAttemptAt: at(3.0) }), at(3.2), cfg).kind, "suspend", "past grace and just failed");
  const susp = row({ status: "SUSPENDED", suspendReason: `${UNPAID_SUSPEND_REASON} (due 2026-11-01)`, renewalLastAttemptAt: at(4) });
  assert.equal(isUnpaidSuspension(susp), true);
  assert.equal(renewalAction(susp, at(5.5), cfg).kind, "charge", "a suspended unpaid server still tries to collect (paying lifts it)");
  assert.equal(renewalAction(susp, at(10), cfg).kind, "terminate");
  assert.equal(renewalAction(row({ status: "SUSPENDED", suspendReason: "Abuse" }), at(1), cfg).kind, "none", "admin suspensions are never billed or ended by the sweep");
  assert.equal(renewalAction(row({ status: "PENDING" }), at(1), cfg).kind, "none");
});

test("renewal policy: a cancelled server is never charged; it ends at the period end", () => {
  assert.equal(renewalAction(row({ cancelAtPeriodEnd: true }), at(-2), cfg).kind, "none", "no warning");
  assert.equal(renewalAction(row({ cancelAtPeriodEnd: true }), at(0), cfg).kind, "end-of-term");
});

test("renewal amount is the frozen price x term (+ tax), never discounted", () => {
  assert.equal(renewalNetCents(row()), 18_999);
  assert.equal(renewalNetCents(row({ termMonths: 12 })), 18_999 * 12);
  assert.equal(renewalTaxCents(10_000, 20), 2_000);
  assert.equal(renewalTaxCents(10_000, 0), 0);
  assert.equal(nextRenewalDate(row({ renewalDate: new Date("2026-01-31T00:00:00Z") })).toISOString(), "2026-02-28T00:00:00.000Z");
  assert.equal(nextRenewalDate(row({ termMonths: 12 })).toISOString(), "2027-11-01T00:00:00.000Z");
});

/* ---------------- tracking data ---------------- */

test("tracking ETA: availability code first, real delivery history once there are 5+ deliveries", () => {
  assert.equal(etaHoursForStock("1H-high"), 2);
  assert.equal(etaHoursForStock("1H-low"), 2);
  assert.equal(etaHoursForStock("24H"), 24);
  assert.equal(etaHoursForStock("72H"), 72);
  assert.equal(etaHoursForStock(null), 24);
  const h = (code: string, hours: number) => ({ stockAtOrder: code, hours });
  assert.equal(historicalEtaHours([h("24H", 5), h("24H", 6)], "24H"), null, "too little history");
  assert.equal(historicalEtaHours([h("24H", 5), h("24H", 6), h("24H", 7), h("24H", 8), h("24H", 30)], "24H"), 7, "median of the same code");
