import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import { isPromoDescription, spendableRealFunds, PROMO_DESCRIPTION_PREFIXES } from "../lib/wallet-funds.ts";
import { renewalAction, renewalNetCents, renewalTaxCents, nextRenewalDate, isUnpaidSuspension, UNPAID_SUSPEND_REASON, type RenewalRow } from "../lib/dedicated/billing-core.ts";
import { etaHoursForStock, historicalEtaHours, buildTrackingData } from "../lib/dedicated/tracking-data.ts";
import { classifyOrder, syncHealth } from "../lib/dedicated/ops-health.ts";
import { correctionCap, isDedicatedInvoiceDescription } from "../lib/dedicated/billing-correction.ts";
import { liveCacheView, LIVE_STALE_MS } from "../lib/dedicated/live-cache.ts";
import { parseDedicatedIntent } from "../lib/dedicated/order-core.ts";
import { sellMonthlyCents, type PricingRules } from "../lib/dedicated/pricing.ts";
import { validateOfferInput } from "../lib/offer-pricing.ts";
import { isCommissionableInvoice } from "../lib/partner-commission.ts";

/**
 * Bare metal release hardening (bm-ops, 2026-10-08): the pure rules behind
 * real-funds-only payment, auto-pay renewals, no refunds / no discounts,
 * tracking ETAs, ops alerts and the live cache. DB paths: test/dedicated-ops-db.test.ts.
 */
const ROOT = path.resolve(__dirname, "..");
const read = (p: string) => readFileSync(path.join(ROOT, p), "utf8");
const DAY = 86_400_000;

/* ---------------- real funds only ---------------- */

test("real funds: promotional credit is held back, never spendable on bare metal", () => {
  assert.deepEqual(spendableRealFunds(10_000, 0), { spendableCents: 10_000, heldCreditCents: 0 }, "real funds only");
  assert.deepEqual(spendableRealFunds(500, 500), { spendableCents: 0, heldCreditCents: 500 }, "credit only");
  assert.deepEqual(spendableRealFunds(12_500, 2_500), { spendableCents: 10_000, heldCreditCents: 2_500 }, "mixed wallet");
  assert.deepEqual(spendableRealFunds(1_000, 5_000), { spendableCents: 0, heldCreditCents: 1_000 }, "credit larger than balance (spent elsewhere) holds the whole balance");
  assert.deepEqual(spendableRealFunds(-50, 0), { spendableCents: 0, heldCreditCents: 0 });
});

test("legacy (untagged) promotional rows are recognised by description", () => {
  for (const d of ["Welcome credit", "Referral bonus — welcome reward", "Referral bonus — you referred a friend", "Promo NXSAVE — 10% bonus", "Promo code redeemed (FREE5)", "Riddle prize — $100 credit (valid toward one VPS)", "Gift code redeemed (ABC)", "Admin credit adjustment", "Admin balance adjustment — goodwill", "Sandbox credit (test funds)"]) {
    assert.equal(isPromoDescription(d), true, d);
  }
  for (const d of ["Stripe payment (cs_test_1)", "PayPal payment (x)", "Card payment for renewal", "Billing correction — box: double charge", "Refund: failed registration a.com"]) {
    assert.equal(isPromoDescription(d), false, d);
  }
});

test("every promotional credit grant site tags its ledger row PROMO (no grant can slip into real funds)", () => {
  const sites: [string, RegExp][] = [
    ["lib/actions.ts", /description: "Welcome credit", fundsKind: "PROMO"/],
    ["lib/actions.ts", /description: `Promo \$\{couponCode!\.toUpperCase\(\)\} — \$\{couponLabel\}`,\s*fundsKind: "PROMO"/],
    ["lib/actions.ts", /description: `Admin credit adjustment`, fundsKind: cents > 0 \? "PROMO" : null/],
    ["lib/discord-auth.ts", /description: "Welcome credit", fundsKind: "PROMO"/],
    ["app/api/auth/google/callback/route.ts", /description: "Welcome credit", fundsKind: "PROMO"/],
    ["lib/riddle.ts", /description: RIDDLE_PRIZE_DESC, fundsKind: "PROMO"/],
    ["lib/actions-growth.ts", /"Referral bonus — welcome reward", fundsKind: "PROMO"/],
    ["lib/actions-growth.ts", /"Referral bonus — you referred a friend",\s*fundsKind: "PROMO"/],
    ["lib/actions-gift.ts", /`Gift code redeemed \(\$\{gift\.code\}\)`,\s*fundsKind: "PROMO"/],
    ["lib/actions-gift.ts", /`Promo code redeemed \(\$\{coupon\.code\}\)`, fundsKind: "PROMO"/],
    ["lib/actions-admin-billing.ts", /amountCents: cents, description, fundsKind: cents > 0 \? "PROMO" : null/],
    ["lib/actions-sandbox.ts", /"Sandbox credit \(test funds\)", fundsKind: "PROMO"/],
  ];
  for (const [f, re] of sites) assert.match(read(f), re, `${f} must tag its promotional credit row`);
  // and each tagged prefix is also in the legacy list (old rows written before the tag)
  for (const p of ["Welcome credit", "Referral bonus", "Promo ", "Riddle prize", "Gift code redeemed", "Admin credit adjustment", "Admin balance adjustment", "Sandbox credit"]) {
    assert.ok((PROMO_DESCRIPTION_PREFIXES as readonly string[]).includes(p), p);
  }
});

test("dedicated money paths debit REAL funds only (never the plain wallet debit)", () => {
  for (const f of ["lib/dedicated/order.ts", "lib/dedicated/ip-order.ts", "worker/dedicated-billing.ts"]) {
    const src = read(f);
    assert.match(src, /debitRealFunds\(/, `${f} uses debitRealFunds`);
    assert.doesNotMatch(src, /\bdebitWallet\(/, `${f} must not use debitWallet`);
  }
  for (const f of ["lib/actions-dedicated-order.ts", "lib/actions-dedicated-ops.ts", "app/dashboard/dedicated/page.tsx", "app/dashboard/dedicated/[id]/page.tsx"]) {
    const src = read(f);
    assert.match(src, /dedicatedSpendable\(/, `${f} splits on spendable real funds`);
    assert.doesNotMatch(src, /balanceCents: user\.balanceCents|balanceCents=\{user\.balanceCents\}/, `${f} must not offer the raw balance`);
  }
});

/* ---------------- non-refundable acknowledgement ---------------- */

test("order intent: acceptedNoRefund is parsed strictly (only literal true)", () => {
  const base = { itemId: "cmabcdefgh12", region: "sgp1", os: "ubuntu-2404", termMonths: 1, memoryId: null, storageId: null, bandwidthId: null, label: "x", orderKey: "k".repeat(16) };
