test("no coupon, promo or discount machinery is reachable from the dedicated checkout code", () => {
  const files = ["lib/dedicated/order.ts", "lib/dedicated/order-core.ts", "lib/dedicated/ip-order.ts", "lib/actions-dedicated-order.ts", "worker/dedicated-billing.ts"];
