test("live cache view: stale/refreshing flags; the panel action never calls the supplier inline", () => {
  const now = Date.now();
  const live = { ok: true, power: "on", bootMode: "disk", hardware: null, network: null, ips: [], templates: [] };
  const fresh = liveCacheView({ liveSnapshot: live, liveFetchedAt: new Date(now - 10_000), liveError: null, liveRefreshRequestedAt: null }, now);
  assert.equal(fresh.stale, false);
  assert.equal(fresh.refreshing, false);
  const old = liveCacheView({ liveSnapshot: live, liveFetchedAt: new Date(now - LIVE_STALE_MS - 1), liveError: null, liveRefreshRequestedAt: new Date(now - 1000) }, now);
  assert.equal(old.stale, true);
  assert.equal(old.refreshing, true);
  assert.ok(old.live, "stale data is still shown");
  const none = liveCacheView({ liveSnapshot: null, liveFetchedAt: null, liveError: "boom", liveRefreshRequestedAt: null }, now);
  assert.equal(none.live, null);
  assert.match(none.error ?? "", /last known/);
  assert.doesNotMatch(none.error ?? "", /boom/, "raw supplier errors never reach the customer");
  const src = read("lib/actions-dedicated-ops.ts");
  const panelFn = src.slice(src.indexOf("export async function loadDedicatedPanel"), src.indexOf("export async function pollDedicatedJobs"));
  assert.doesNotMatch(panelFn, /readDedicatedLive\(|serverBlocks\(|get\(/, "loadDedicatedPanel reads the DB snapshot only");
});

