import { test, before, after } from "node:test";
import assert from "node:assert/strict";

/**
 * bm-ops DB tests (2026-10-08) against a THROWAWAY database only: real funds vs
 * promotional credit on every bare metal money path, the non-refundable
 * acknowledgement, the card leg, auto-pay renewals (wallet, card, failure,
 * grace, suspension, termination, cancel-at-period-end, idempotency), billing
 * corrections, extra IPs end to end in the supplier MOCK, the live-panel cache
 * (single-flight + a deliberately slow mock), tracking data and stuck-order
 * alerts. No supplier call, no Stripe call (a fake card charger and a fake
 * Checkout session object), no email.
 *
 * Opt-in and fail-closed: runs only with BM_OPS_DB_TEST=1 AND a DATABASE_URL on
 * node-2's private throwaway cluster (127.0.0.1:5433/wt_*), or a 127.0.0.1
 * non-5432 /dedprev scratch DB.
 *   /opt/nxeon/scripts/devhost db push
 *   /opt/nxeon/scripts/devhost run --lock -- env BM_OPS_DB_TEST=1 NXEON_DEDICATED_OVH_MOCK=1 npx tsx --test test/dedicated-ops-db.test.ts
 */
const url = process.env.DATABASE_URL ?? "";
const safe = process.env.BM_OPS_DB_TEST === "1" && process.env.NODE_ENV !== "production" &&
  (/^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:5433\/wt_[a-z0-9_-]+(\?.*)?$/i.test(url) || /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:(?!5432\b)\d+\/dedprev$/.test(url));
const skip = safe ? false : "set BM_OPS_DB_TEST=1 with a throwaway node-2 DATABASE_URL to run";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
let order: typeof import("../lib/dedicated/order.ts");
let funds: typeof import("../lib/wallet-funds.ts");
let billing: typeof import("../worker/dedicated-billing.ts");
let fulfil: typeof import("../lib/fulfil-checkout.ts")["fulfilRetrievedCheckoutSession"];
let itemId = "";
const DC = "bhs";
const REGION = "bhs1";
const tag = `t${Date.now().toString(36)}`;
const key = () => `k${Date.now()}${Math.random().toString(36).slice(2, 12)}`;
const DAY = 86_400_000;

async function mkUser(balanceCents: number, promoCents = 0) {
  const u = await db.user.create({ data: { email: `${tag}-${Math.random().toString(36).slice(2, 8)}@example.test`, passwordHash: "x", name: "BM Ops Test", balanceCents: balanceCents + promoCents, signupCreditCents: promoCents } });
  if (promoCents > 0) await db.walletTransaction.create({ data: { userId: u.id, amountCents: promoCents, description: "Welcome credit", fundsKind: "PROMO" } });
  return u;
}
const intentFor = (over: Record<string, unknown> = {}) => ({ itemId, region: REGION, os: "ubuntu-2404", termMonths: 1 as const, memoryId: null, storageId: null, bandwidthId: null, label: "Ops box", orderKey: key(), acceptedNoRefund: true, ...over });

before(async () => {
  if (!safe) return;
  process.env.STRIPE_SECRET_KEY = "sk_test_fake_never_called";
  db = (await import("../lib/db.ts")).db;
  order = await import("../lib/dedicated/order.ts");
  funds = await import("../lib/wallet-funds.ts");
  billing = await import("../worker/dedicated-billing.ts");
  fulfil = (await import("../lib/fulfil-checkout.ts")).fulfilRetrievedCheckoutSession;
  // a tiny synthetic catalogue: one plan in one datacenter, in stock (24H)
  await db.setting.upsert({ where: { key: "dedicated_enabled_regions" }, update: { value: REGION }, create: { key: "dedicated_enabled_regions", value: REGION } });
  const it = await db.dedicatedCatalogItem.create({
    data: {
      subsidiary: "WE", catalog: "eco", planCode: `${tag}-plan`, productCode: `${tag}-prod`, range: "rise", name: "TEST-1", invoiceName: "TEST-1",
      cpuBrand: "AMD", cpuModel: "EPYC 4344P", cpuCount: 1, cpuCores: 8, cpuThreads: 16, cpuFrequencyGhz: 3.8, cpuBoostGhz: 5.3, defaultRamGb: 64, defaultStorage: "2x 960GB NVMe",
      defaultBandwidthMbps: 1000, datacenters: [DC], currency: "USD", monthlyCents: 10_000, setupCents: 0, terms: [], promotions: [], spec: {}, hash: tag, visible: true,
      options: { create: [
        { family: "memory", planCode: `${tag}-ram`, productCode: `${tag}-ram`, label: "64GB DDR5", isDefault: true, monthlyCents: 0, ramGb: 64, spec: {} },
        { family: "storage", planCode: `${tag}-disk`, productCode: `${tag}-disk`, label: "2x 960GB NVMe", isDefault: true, monthlyCents: 0, spec: {} },
      ] },
    },
  });
  itemId = it.id;
  await db.dedicatedAvailability.create({ data: { feed: "ca", planCode: it.planCode, fqn: `${tag}.fqn`, memory: `${tag}-ram`, storage: `${tag}-disk`, datacenter: DC, availability: "24H", fetchedAt: new Date() } });
  await db.dedicatedCatalogSync.create({ data: { trigger: "script", subsidiary: "WE", status: "OK", finishedAt: new Date() } }); // bumps the snapshot stamp
});
after(async () => { if (safe) await db.$disconnect(); });

/* ---------------- real funds only + acknowledgement ---------------- */

test("order: credit only / mixed wallet are refused; real funds pay; credit is never consumed", { skip }, async () => {
  const probe = await mkUser(0);
  const q = await order.quoteDedicatedOrder(intentFor(), probe, { previewAll: true });
  const T = q.money.totalCents;
  assert.ok(T > 0);

  // credit only: the whole balance is promotional
  const a = await mkUser(0, T + 5_000);
  assert.deepEqual(await funds.dedicatedSpendable(db, a), { balanceCents: T + 5_000, spendableCents: 0, heldCreditCents: T + 5_000 });
  const ia = intentFor();
  await assert.rejects(order.placeDedicatedOrder(a, ia, { previewAll: true, via: "wallet" }), /Promotional and welcome credit can't be used/);
  assert.equal(await db.dedicatedServer.count({ where: { orderKey: ia.orderKey } }), 0, "nothing written");
  assert.equal((await db.user.findUniqueOrThrow({ where: { id: a.id } })).balanceCents, T + 5_000, "nothing debited");
  assert.equal(await db.fulfilledSession.count({ where: { stripeSessionId: `dedorder:${a.id}:${ia.orderKey}` } }), 0, "claim released for a retry");

  // mixed: real funds one cent short, credit would cover it -> refused
  const b = await mkUser(T - 1, 2_500);
  await assert.rejects(order.placeDedicatedOrder(b, intentFor(), { previewAll: true, via: "wallet" }), /Promotional and welcome credit can't be used/);
  // one more real cent -> placed, and the promotional 2,500 is still there afterwards
  await db.user.update({ where: { id: b.id }, data: { balanceCents: { increment: 1 } } });
  await db.walletTransaction.create({ data: { userId: b.id, amountCents: 1, description: "Stripe payment (cs_test_cent)", stripeSessionId: `cs_test_cent_${tag}` } });
  const b2 = await db.user.findUniqueOrThrow({ where: { id: b.id } });
  const ib = intentFor();
  const placed = await order.placeDedicatedOrder(b2, ib, { previewAll: true, via: "wallet" });
  assert.equal(placed.created, true);
  assert.equal((await db.user.findUniqueOrThrow({ where: { id: b.id } })).balanceCents, 2_500, "only real funds were used");
  const s = await db.dedicatedServer.findUniqueOrThrow({ where: { id: placed.serverId } });
  assert.ok(s.acceptedNoRefundAt, "acknowledgement recorded");
  assert.equal(s.stockAtOrder, "24H", "availability code recorded (admin-only) for the tracking ETA");
  // idempotent on the order key
  assert.equal((await order.placeDedicatedOrder(b2, ib, { previewAll: true, via: "wallet" })).created, false);

  // real funds only
  const c = await mkUser(T);
  await order.placeDedicatedOrder(c, intentFor(), { previewAll: true, via: "wallet" });
  assert.equal((await db.user.findUniqueOrThrow({ where: { id: c.id } })).balanceCents, 0);
});

test("order: the non-refundable acknowledgement is required before wallet money moves", { skip }, async () => {
  const u = await mkUser(1_000_000);
  const i = intentFor({ acceptedNoRefund: false });
  await assert.rejects(order.placeDedicatedOrder(u, i, { previewAll: true, via: "wallet" }), /non-refundable/);
  assert.equal((await db.user.findUniqueOrThrow({ where: { id: u.id } })).balanceCents, 1_000_000);
  assert.equal(await db.dedicatedServer.count({ where: { orderKey: i.orderKey } }), 0);
});

test("card leg: credit-only wallet + card for the full total; credit untouched; stamped total debited once", { skip }, async () => {
  const u = await mkUser(0, 700);
  const i = intentFor();
  const q = await order.quoteDedicatedOrder(i, u, { previewAll: true });
  const sp = await funds.dedicatedSpendable(db, u);
  assert.equal(sp.spendableCents, 0, "the wizard offers no wallet money for this account");
  const session = { id: `cs_test_bmops_${key()}`, payment_status: "paid", amount_total: q.money.totalCents, currency: "usd", payment_intent: null, customer: null,
    metadata: { nxeonUserId: u.id, nxeonDedicatedOrder: JSON.stringify(i), nxeonDedicatedOrderPrice: JSON.stringify(q.money) } } as never;
  const r1 = await fulfil(session, "");
  const r2 = await fulfil(session, "");
  assert.equal(r1.fulfilled, true, r1.error);
  assert.equal(r2.fulfilled, false);
  assert.equal((await db.user.findUniqueOrThrow({ where: { id: u.id } })).balanceCents, 700, "card paid it all; the 700 welcome credit is still held");
  const s = await db.dedicatedServer.findFirstOrThrow({ where: { orderKey: i.orderKey } });
  assert.ok(s.acceptedNoRefundAt);
});

/* ---------------- auto-pay renewals ---------------- */

type Notes = { user: string[]; admin: string[] };
function deps(now: Date, card: "none" | "ok" | "decline", notes: Notes = { user: [], admin: [] }) {
  return {
    now: () => now,
    hasCard: () => card !== "none",
    chargeCard: card === "none" ? null : (async (o: { user: { id: string }; amountCents: number; idempotencyKey: string }) => {
      if (card === "decline") return { ok: false as const, reason: "declined" };
      const pi = `pi_test_${o.idempotencyKey}`;
      const exists = await db.walletTransaction.findUnique({ where: { stripePaymentIntentId: pi } });
      if (!exists) {
        await db.$transaction([
          db.walletTransaction.create({ data: { userId: o.user.id, amountCents: o.amountCents, description: "Card payment for renewal (test)", stripePaymentIntentId: pi } }),
          db.user.update({ where: { id: o.user.id }, data: { balanceCents: { increment: o.amountCents } } }),
        ]);
      }
      return { ok: true as const, amountCents: o.amountCents, paymentIntentId: pi };
    }),
    taxRatePercent: async () => ({ ratePercent: 0, country: "" }),
    notify: async (_u: string, t: string) => { notes.user.push(t); },
    notifyAdmins: async (t: string) => { notes.admin.push(t); },
  };
}
async function activeServer(userId: string, renewalDate: Date, over: Record<string, unknown> = {}) {
  return db.dedicatedServer.create({ data: { userId, label: `Renew ${key().slice(-5)}`, cpu: "AMD EPYC 4344P", region: REGION, status: "ACTIVE", renewalDate, renewalMonthlyCents: 15_000, termMonths: 1, ...over } });
}

test("renewal: real wallet funds pay; promotional credit is not consumed; a second run never charges twice", { skip }, async () => {
  const due = new Date(Date.now() - 60_000);
  const u = await mkUser(15_000, 3_000);
  const s = await activeServer(u.id, due);
  const r = await billing.renewDedicatedServer(s.id, deps(new Date(), "none"));
  assert.equal(r.ok, true, JSON.stringify(r));
  const again = await billing.renewDedicatedServer(s.id, deps(new Date(), "none"));
  assert.equal(again.ok, false);
  assert.equal((await db.user.findUniqueOrThrow({ where: { id: u.id } })).balanceCents, 3_000, "15,000 real funds used once, the 3,000 credit untouched");
  const row = await db.dedicatedServer.findUniqueOrThrow({ where: { id: s.id } });
  assert.equal(row.renewalDate?.getTime(), new Date(new Date(due).setUTCMonth(due.getUTCMonth() + 1)).getTime() || row.renewalDate?.getTime());
  assert.ok(row.renewalDate!.getTime() > Date.now() + 25 * DAY, "advanced one term");
  const inv = await db.invoice.findFirstOrThrow({ where: { id: row.invoiceIds[row.invoiceIds.length - 1] } });
  assert.equal(inv.status, "PAID");
  assert.equal(inv.amountCents, 15_000, "the frozen price, no discount");
});

test("renewal: credit-only wallet + saved card -> the card pays the full amount, credit untouched", { skip }, async () => {
  const u = await mkUser(0, 20_000);
  const s = await activeServer(u.id, new Date(Date.now() - 60_000));
  const r = await billing.renewDedicatedServer(s.id, deps(new Date(), "ok"));
  assert.equal(r.ok, true, JSON.stringify(r));
  assert.equal(r.ok && r.viaCardCents, 15_000);
  assert.equal((await db.user.findUniqueOrThrow({ where: { id: u.id } })).balanceCents, 20_000);
});

test("renewal: failure -> grace (still running) -> suspended -> paying lifts it -> unpaid past 10 days ends it", { skip }, async () => {
  const due = new Date(Date.now() - 60_000);
  const u = await mkUser(0, 50_000); // only credit: must fail
  const s = await activeServer(u.id, due);
  const notes: Notes = { user: [], admin: [] };
  let out = await billing.dedicatedBillingSweep(deps(new Date(), "decline", notes));
  let row = await db.dedicatedServer.findUniqueOrThrow({ where: { id: s.id } });
  assert.ok(out.failed >= 1);
  assert.equal(row.status, "ACTIVE", "grace: keeps running");
  assert.ok(row.renewalFailedAt);
  assert.ok(notes.user.some((t) => /Renewal payment failed/.test(t)));
  // 3.5 days later the retry fails again -> suspended
  await db.dedicatedServer.update({ where: { id: s.id }, data: { renewalLastAttemptAt: new Date(due.getTime() + 2 * DAY) } });
  out = await billing.dedicatedBillingSweep(deps(new Date(due.getTime() + 3.5 * DAY), "decline", notes));
  row = await db.dedicatedServer.findUniqueOrThrow({ where: { id: s.id } });
  assert.equal(row.status, "SUSPENDED");
  assert.match(row.suspendReason ?? "", /^Unpaid renewal/);
  // the customer adds REAL funds -> the next sweep renews and lifts the suspension
  await db.user.update({ where: { id: u.id }, data: { balanceCents: { increment: 15_000 } } });
  await db.dedicatedServer.update({ where: { id: s.id }, data: { renewalLastAttemptAt: new Date(due.getTime() + 3 * DAY) } });
  out = await billing.dedicatedBillingSweep(deps(new Date(due.getTime() + 4.5 * DAY), "none", notes));
  row = await db.dedicatedServer.findUniqueOrThrow({ where: { id: s.id } });
  assert.equal(row.status, "ACTIVE", "paying lifts an unpaid suspension");
  assert.equal(row.renewalFailedAt, null);
  assert.equal((await db.user.findUniqueOrThrow({ where: { id: u.id } })).balanceCents, 50_000, "credit untouched throughout");

  // another server stays unpaid -> ended after 10 days, staff told to end it upstream
  const s2 = await activeServer(u.id, due);
  await billing.dedicatedBillingSweep(deps(new Date(due.getTime() + 0.1 * DAY), "decline", notes));
  await db.dedicatedServer.update({ where: { id: s2.id }, data: { renewalLastAttemptAt: new Date(due.getTime() + 2 * DAY) } });
  await billing.dedicatedBillingSweep(deps(new Date(due.getTime() + 3.5 * DAY), "decline", notes));
  await billing.dedicatedBillingSweep(deps(new Date(due.getTime() + 10.5 * DAY), "decline", notes));
  const r2 = await db.dedicatedServer.findUniqueOrThrow({ where: { id: s2.id } });
  assert.equal(r2.status, "CANCELLED");
  assert.ok(notes.admin.some((t) => /End bare metal machine upstream/.test(t)));
});

test("renewal: cancelled at period end -> never charged, ends at the period end, nothing refunded", { skip }, async () => {
  const u = await mkUser(100_000);
  const s = await activeServer(u.id, new Date(Date.now() - 60_000), { cancelAtPeriodEnd: true });
  assert.equal((await billing.renewDedicatedServer(s.id, deps(new Date(), "ok"))).ok, false);
  await billing.dedicatedBillingSweep(deps(new Date(), "ok"));
  const row = await db.dedicatedServer.findUniqueOrThrow({ where: { id: s.id } });
  assert.equal(row.status, "CANCELLED");
  assert.equal((await db.user.findUniqueOrThrow({ where: { id: u.id } })).balanceCents, 100_000, "no charge, no refund");
});

test("renewal: T-3d warning only when it will fail (no real funds, no card), once per period", { skip }, async () => {
  const notes: Notes = { user: [], admin: [] };
  const u = await mkUser(0, 99_000);
  const s = await activeServer(u.id, new Date(Date.now() + 2 * DAY));
  await billing.dedicatedBillingSweep(deps(new Date(), "none", notes));
  await billing.dedicatedBillingSweep(deps(new Date(), "none", notes));
  assert.equal(notes.user.filter((t) => t.includes(s.label)).length, 1);
});

/* ---------------- billing correction, IP orders, refund guard ---------------- */

test("billing correction: capped at what was paid, needs reason + typed name, audited, credits real funds", { skip }, async () => {
  const { applyBillingCorrection, isDedicatedInvoice } = await import("../lib/dedicated/billing-correction.ts");
  const u = await mkUser(0);
  const inv = await db.invoice.create({ data: { userId: u.id, number: Math.floor(Math.random() * 1e9), description: "Bare Metal Dedicated Server — corr", status: "PAID", amountCents: 10_000 } as never });
  const s = await activeServer(u.id, new Date(Date.now() + 20 * DAY), { invoiceIds: [inv.id] });
  assert.equal(await isDedicatedInvoice(inv), true);
  const admin = await mkUser(0);
  await assert.rejects(applyBillingCorrection({ serverId: s.id, adminId: admin.id, kind: "BILLING_ERROR", amountCents: 500, reason: "short", confirm: s.label }), /10 characters/);
  await assert.rejects(applyBillingCorrection({ serverId: s.id, adminId: admin.id, kind: "BILLING_ERROR", amountCents: 500, reason: "charged twice by mistake", confirm: "nope" }), /Type the server name/);
  await assert.rejects(applyBillingCorrection({ serverId: s.id, adminId: admin.id, kind: "REFUND", amountCents: 500, reason: "charged twice by mistake", confirm: s.label }), /BILLING_ERROR or NOT_DELIVERED/);
  await assert.rejects(applyBillingCorrection({ serverId: s.id, adminId: admin.id, kind: "BILLING_ERROR", amountCents: 10_001, reason: "charged twice by mistake", confirm: s.label }), /At most 100\.00/);
  await applyBillingCorrection({ serverId: s.id, adminId: admin.id, kind: "BILLING_ERROR", amountCents: 6_000, reason: "charged twice by mistake", confirm: s.label });
  await assert.rejects(applyBillingCorrection({ serverId: s.id, adminId: admin.id, kind: "BILLING_ERROR", amountCents: 4_001, reason: "charged twice by mistake", confirm: s.label }), /At most 40\.00/);
  const after = await db.user.findUniqueOrThrow({ where: { id: u.id } });
  assert.equal(after.balanceCents, 6_000);
  assert.equal((await funds.dedicatedSpendable(db, after)).spendableCents, 6_000, "a correction returns REAL funds");
  assert.equal(await db.auditLog.count({ where: { action: "dedicated.billing_correction", detail: { contains: s.id } } }), 1);
});

test("extra IPs: real funds only, admin approval, ordered in the MOCK, attached, renewal raised; non-delivery is a correction", { skip }, async () => {
  const ipo = await import("../lib/dedicated/ip-order.ts");
  const { dedicatedJobsTick } = await import("../worker/dedicated-jobs.ts");
  const { MockOvh } = await import("../lib/dedicated/ovh-mock.ts");
  let t = Date.now();
  const mock = new MockOvh(false, () => t, 1000);
  const sn = `ns-${tag}.example`;
  mock.seed("ns-other.example", ["198.18.0.1/32"]);
  mock.seed(sn);
  const u = await mkUser(0, 50_000);
  const s = await activeServer(u.id, new Date(Date.now() + 15 * DAY), { providerServiceName: sn, ipv4: ["203.0.113.40"] });
  await assert.rejects(ipo.placeDedicatedIpOrder(u, s.id, 1, key()), /Promotional and welcome credit can't be used/);
  await db.user.update({ where: { id: u.id }, data: { balanceCents: { increment: 5_000 } } });
  const u2 = await db.user.findUniqueOrThrow({ where: { id: u.id } });
  const placed = await ipo.placeDedicatedIpOrder(u2, s.id, 4, key());
  const o = await db.dedicatedIpOrder.findUniqueOrThrow({ where: { id: placed.orderId } });
  assert.equal(o.status, "PAID");
  assert.ok((await db.user.findUniqueOrThrow({ where: { id: u.id } })).balanceCents >= 50_000, "credit untouched");
  const admin = await mkUser(0);
  await ipo.approveIpOrder(o.id, admin.id);
  const jdeps = {
    client: () => ({ get: (p: string) => mock.get(p), write: async (r: any) => ({ ok: true as const, response: await mock.send(r.method, r.path, r.body) }) }),
    notifyReady: async () => {}, now: () => new Date(t), dryRunDefault: async () => false, protectedNames: async () => new Set<string>(),
  };
  for (let i = 0; i < 12; i++) {
    await dedicatedJobsTick(jdeps);
    const ord = await db.dedicatedIpOrder.findUniqueOrThrow({ where: { id: o.id } });
    if (ord.status === "DONE" || ord.status === "FAILED") break;
    t += 15_000;
    await db.dedicatedJob.updateMany({ where: { dedicatedServerId: s.id }, data: { updatedAt: new Date(Date.now() - 20_000) } });
  }
  const done = await db.dedicatedIpOrder.findUniqueOrThrow({ where: { id: o.id } });
  assert.equal(done.status, "DONE");
  assert.equal(done.ips.length, 1);
  assert.match(done.ips[0], /\/30$/);
  const srv = await db.dedicatedServer.findUniqueOrThrow({ where: { id: s.id } });
  assert.equal(srv.renewalMonthlyCents, 15_000 + o.unitMonthlyCents * 4);
  assert.equal(srv.extraIpMonthlyCents, o.unitMonthlyCents * 4);
  assert.ok(mock.writes().some((w) => w.path.endsWith("/configuration") && (w.body as { value?: string })?.value === sn), "routed to THIS server");
  // a second order that can't be delivered: closed as NOT_DELIVERED (wallet credit), never a refund tool
  const p2 = await ipo.placeDedicatedIpOrder(await db.user.findUniqueOrThrow({ where: { id: u.id } }), s.id, 1, key());
  const before = (await db.user.findUniqueOrThrow({ where: { id: u.id } })).balanceCents;
  await assert.rejects(ipo.rejectIpOrder(p2.orderId, admin.id, "no addresses available in that location", "wrong"), /Type the server name/);
  await ipo.rejectIpOrder(p2.orderId, admin.id, "no addresses available in that location", srv.label);
  const o2 = await db.dedicatedIpOrder.findUniqueOrThrow({ where: { id: p2.orderId } });
  assert.equal(o2.status, "REJECTED");
  assert.equal((await db.user.findUniqueOrThrow({ where: { id: u.id } })).balanceCents, before + o2.chargedCents);
  assert.equal(await db.dedicatedBillingCorrection.count({ where: { ipOrderId: o2.id, kind: "NOT_DELIVERED" } }), 1);
});

test("jobs: a job stuck RUNNING is failed loudly (not re-run); a timed-out IP order is marked FAILED", { skip }, async () => {
