  assert.equal(await loadTrackingData(s.id, "someone-else"), null, "owner-checked");
  const admins: string[] = [];
  const d = { now: () => new Date(), notifyAdmins: async (x: string) => { admins.push(x); } };
  await billing.dedicatedOpsAlerts(d, true);
  await billing.dedicatedOpsAlerts(d, true);
  assert.equal(admins.filter((x) => x.includes("Late box")).length, 1);
});

