  const { dedicatedJobsTick } = await import("../worker/dedicated-jobs.ts");
  const u = await mkUser(0);
  const s = await activeServer(u.id, new Date(Date.now() + 15 * DAY), { providerServiceName: `ns-stuck-${tag}.example` });
  const stuck = await db.dedicatedJob.create({ data: { dedicatedServerId: s.id, userId: u.id, kind: "REBOOT_HARD", payload: {}, status: "RUNNING" } });
  await db.$executeRaw`UPDATE "DedicatedJob" SET "updatedAt" = now() - interval '30 minutes' WHERE id = ${stuck.id}`;
  const io = await db.dedicatedIpOrder.create({ data: { dedicatedServerId: s.id, userId: u.id, quantity: 1, unitMonthlyCents: 300, chargedCents: 100, orderKey: key(), status: "ORDERING" } });
  const wj = await db.dedicatedJob.create({ data: { dedicatedServerId: s.id, userId: u.id, kind: "IP_ORDER", payload: { ipOrderId: io.id }, status: "WAITING", startedAt: new Date(Date.now() - 4 * 3_600_000) } });
  await dedicatedJobsTick({ client: () => ({ get: async () => null, write: async () => ({ ok: false as const, error: "no" }) }), notifyReady: async () => {}, now: () => new Date(), dryRunDefault: async () => true, protectedNames: async () => new Set<string>() });
  assert.equal((await db.dedicatedJob.findUniqueOrThrow({ where: { id: stuck.id } })).status, "FAILED");
