});

/* ---------------- live cache ---------------- */

test("live cache: 50 concurrent viewers -> ONE refresh request; worker stores the snapshot; render reads the DB (slow supplier measured)", { skip }, async () => {
  const { requestLiveRefresh, liveCacheView } = await import("../lib/dedicated/live-cache.ts");
  const { refreshDedicatedLive, dedicatedLiveRefreshTick } = await import("../worker/dedicated-live.ts");
  const { readDedicatedLive } = await import("../lib/dedicated/live.ts");
  const { MockOvh } = await import("../lib/dedicated/ovh-mock.ts");
  const sn = `ns-live-${tag}.example`;
  const mock = new MockOvh(false);
  mock.seed(sn, ["203.0.113.50/32", "2001:db8:50::/64"]);
  const u = await mkUser(0);
  const s = await activeServer(u.id, new Date(Date.now() + 15 * DAY), { providerServiceName: sn });
  const placed = (await Promise.all(Array.from({ length: 50 }, () => requestLiveRefresh(s.id)))).filter(Boolean).length;
  assert.equal(placed, 1, "single-flight");
  const n = await dedicatedLiveRefreshTick({ get: (p) => mock.get(p) });
  assert.ok(n >= 1);
  const row = await db.dedicatedServer.findUniqueOrThrow({ where: { id: s.id } });
  const v = liveCacheView(row, Date.now());
  assert.equal(v.live?.power, "on");
  assert.equal(v.refreshing, false);
  assert.equal(v.stale, false);

  // BEFORE (old behaviour: the panel read the supplier inline) vs AFTER (DB snapshot), supplier made 8 s slow
  mock.delayMs = 8_000;
  const t0 = Date.now();
  await readDedicatedLive(sn, (p) => mock.get(p));
  const beforeMs = Date.now() - t0;
  const t1 = Date.now();
  const r2 = await db.dedicatedServer.findUniqueOrThrow({ where: { id: s.id } });
  liveCacheView(r2, Date.now());
  const afterMs = Date.now() - t1;
  console.log(`[bm-ops measure] live panel data with an 8 s supplier: inline supplier read ${beforeMs} ms, cached DB read ${afterMs} ms`);
  assert.ok(beforeMs >= 8_000);
  assert.ok(afterMs < 1_000);

  // supplier down: last good snapshot kept, customer-safe error flagged
  const ok = await refreshDedicatedLive(s.id, async () => { throw new Error("upstream 503 from api.example"); });
  assert.equal(ok, false);
  const r3 = await db.dedicatedServer.findUniqueOrThrow({ where: { id: s.id } });
  const v3 = liveCacheView(r3, Date.now());
  assert.equal(v3.live?.power, "on", "stale data still shown");
  assert.ok(v3.error && !/503|api\./.test(v3.error));
});

