test("virtual MAC: created for an extra IPv4 only, routed to THIS server, readable in the live view (mock)", async () => {
  const { deps, advance, mock } = setup();
  mock.seed(SN, ["203.0.113.40/32", "198.51.100.8/30", "2001:db8:40::/64"]);
  const s = server({ ipv4: ["203.0.113.40"] });
  const refusedMain = await runJobStep(job("VMAC_CREATE", { ip: "203.0.113.40", vmName: "vm1" }), s, deps);
  assert.equal(refusedMain.status, "FAILED");
  assert.match(refusedMain.error ?? "", /main address/);
  const refusedForeign = await runJobStep(job("VMAC_CREATE", { ip: "192.0.2.9", vmName: "vm1" }), s, deps);
  assert.match(refusedForeign.error ?? "", /does not belong/);
  const dry = await runJobStep(job("VMAC_CREATE", { ip: "198.51.100.9", vmName: "vm1" }, { dryRun: true }), s, deps);
  assert.match(dry.step, /Dry run/);
  const before = mock.writes().length;
  const r = await runToEnd(job("VMAC_CREATE", { ip: "198.51.100.9", vmName: "web-vm" }), s, deps, advance);
  assert.equal(r.status, "DONE", r.error);
  const w = mock.writes().slice(before);
  assert.equal(w.length, 1);
  assert.equal(w[0].path, `/dedicated/server/${SN}/virtualMac`);
  const { readDedicatedLive } = await import("../lib/dedicated/live.ts");
  const live = await readDedicatedLive(SN, (p) => mock.get(p));
  assert.deepEqual(live.vmacs?.map((m) => [m.ip, m.vm]), [["198.51.100.9", "web-vm"]]);
  assert.match(live.vmacs![0].mac, /^02:00:00:/);
});
EOF
