test("nothing outside the feature links to the unreleased routes (nav, footer, header, sitemap)", () => {
  const ALLOWED = (f: string) =>
    f.startsWith("components/dedicated/") ||
    f.startsWith("components/admin/dedicated/") ||
    f.startsWith("app/admin/dedicated/") ||
    f.startsWith("app/admin/preview/dedicated/") ||
    f.startsWith("app/dashboard/dedicated/") ||
    f.startsWith("app/(marketing)/dedicated-servers/") ||
    f.startsWith("app/nxm/dedicated-servers/") ||
    f.startsWith("app/nxm/_pages/dedicated-servers/") ||
    f === "app/nxm/_data/dedicated-servers.ts" ||
    f === "app/nxm/_components/dedicated-nav.ts" ||
    f === "app/nxm/_data/live-routes.json" ||
    f === "app/nxm/_seo/registry.ts" ||
    f === "lib/sitemap-sections.ts" ||
    f.startsWith("lib/dedicated/") ||
    f === "lib/actions-dedicated.ts" ||
    f === "lib/actions-dedicated-customer.ts" ||
    f === "lib/actions-dedicated-order.ts" ||
    f === "lib/actions-dedicated-ops.ts" ||
    f === "lib/actions-dedicated-ops-admin.ts";
  const hits: string[] = [];
  for (const f of [...walk("app"), ...walk("components"), ...walk("lib")]) {
    if (ALLOWED(f)) continue;
    const src = read(f);
    if (/["'`]\/dedicated-servers\b/.test(src) || /["'`]\/dashboard\/dedicated\b/.test(src)) hits.push(f);
  }
  assert.deepEqual(hits, [], `unreleased dedicated routes linked from: ${hits.join(", ")}`);
});

test("admin previews are admin-only and do not use the public gate", () => {
  for (const f of ["app/admin/preview/dedicated/page.tsx", "app/admin/preview/dedicated/dashboard/page.tsx"]) {
    const src = read(f);
    assert.match(src, /await requireAdmin\(\)/, f);
    assert.doesNotMatch(src, /requireDedicatedPublic/, f);
  }
});

