// SCRATCH (not committed): admin screenshots for bm-ops, run ON node-2 against the dev server.
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
const BASE = `http://127.0.0.1:${process.env.PORT}`;
const TOK = process.env.BM_TOKEN;
const SERVER = process.env.BM_SERVER;
const OUT = "./.bmops-shots";
mkdirSync(OUT, { recursive: true });
const browser = await chromium.launch({ args: ["--disable-dev-shm-usage"] });
const pages = [["ops", "/admin/dedicated/ops"], ["server", `/admin/dedicated/servers/${SERVER}`]];
for (const theme of ["dark", "light"]) for (const w of [1440, 390]) {
  const ctx = await browser.newContext({ viewport: { width: w, height: 900 }, isMobile: w < 600 });
  await ctx.addCookies([{ name: "nxeon_session", value: TOK, domain: "127.0.0.1", path: "/" }, { name: "nxeon_authed", value: "1", domain: "127.0.0.1", path: "/" }]);
  await ctx.addInitScript((t) => { try { localStorage.setItem("nxeon.admin.theme", t); } catch {} }, theme);
  const page = await ctx.newPage();
  page.on("pageerror", (e) => console.log("PAGEERROR", e.message));
  for (const [name, path] of pages) {
    for (let i = 0; i < 5; i++) { try { const r = await page.goto(BASE + path, { waitUntil: "networkidle", timeout: 180000 }); console.log(name, theme, w, r?.status()); break; } catch (e) { console.log("retry", e.message.slice(0, 80)); await page.waitForTimeout(10000); } }
    await page.waitForTimeout(1500);
    await page.screenshot({ path: `${OUT}/${name}-${theme}-${w}.png`, fullPage: true });
  }
  await ctx.close();
}
await browser.close();

