104	export type RenewResult = { ok: true; invoiceId: string; chargedCents: number; viaCardCents: number; nextRenewal: Date } | { ok: false; reason: string; already?: boolean };
105	
106	/**
107	 * Try to renew ONE server for its current period. Used by the sweep and by the
108	 * admin "Renew now" control. Idempotent per period (CAS on renewalDate).
109	 */
110	export async function renewDedicatedServer(serverId: string, deps: BillingDeps = defaultBillingDeps(), actor: string | null = null): Promise<RenewResult> {
111	  const s = await db.dedicatedServer.findUnique({ where: { id: serverId } });
112	  if (!s || !s.renewalDate || s.renewalMonthlyCents == null) return { ok: false, reason: "Not renewable (no renewal date or price)." };
113	  if (!(s.status === "ACTIVE" || isUnpaidSuspension(s))) return { ok: false, reason: `Not renewable while ${s.status.toLowerCase()}.` };
114	  if (s.cancelAtPeriodEnd) return { ok: false, reason: "Cancelled at period end: not renewed." };
115	  const user = await db.user.findUnique({ where: { id: s.userId } });
116	  if (!user) return { ok: false, reason: "Customer not found." };
117	  const now = deps.now();
118	  const period = s.renewalDate;
119	  const net = renewalNetCents(s);
120	  const tax = await deps.taxRatePercent({ billingCountry: user.billingCountry ?? null, vatId: user.vatId ?? null });
121	  const taxCents = renewalTaxCents(net, tax.ratePercent);
122	  const total = net + taxCents;
123	  const next = nextRenewalDate(s);
124	  const what = `Bare Metal Dedicated Server renewal — ${s.label}`.slice(0, 190);
125	
126	  await db.dedicatedServer.updateMany({ where: { id: s.id, renewalDate: period }, data: { renewalLastAttemptAt: now, renewalAttempts: { increment: 1 } } });
127	
128	  // 1) real funds in the wallet first, the card for the shortfall
129	  const promo = await promoCreditGrantedCents(db, user.id);
130	  const { spendableCents } = spendableRealFunds(user.balanceCents, promo);
131	  let viaCardCents = 0;
132	  if (spendableCents < total) {
133	    const split = walletSplit({ dueCents: total, balanceCents: spendableCents, useWallet: true });
134	    const cardUser: CardUser = { id: user.id, email: user.email, name: user.name, stripeCustomerId: user.stripeCustomerId, stripePaymentMethodId: user.stripePaymentMethodId, cardBrand: user.cardBrand, cardLast4: user.cardLast4, cardExpMonth: user.cardExpMonth, cardExpYear: user.cardExpYear };
135	    if (!deps.chargeCard || !deps.hasCard(cardUser) || split.cardCents <= 0) {
136	      return failed(s, deps, now, "no-funds", spendableCents, total);
137	    }
138	    const r = await deps.chargeCard({
139	      user: cardUser,
140	      amountCents: split.cardCents,
141	      description: `${s.label} bare metal renewal`,
142	      marker: `renew:ded:${s.id}:${period.toISOString()}`,
143	      idempotencyKey: `nxeon_dedrenew_${s.id}_${period.getTime()}_${split.cardCents}`,
144	      metadata: { nxeonDedicatedServerId: s.id, nxeonPeriodStart: period.toISOString(), nxeonKind: "dedicated_renewal" },
145	    });
146	    if (!r.ok) return failed(s, deps, now, `card-${r.reason}`, spendableCents, total);
147	    viaCardCents = r.amountCents;
148	  }
149	
150	  // 2) one transaction: CAS the period, debit REAL funds, PAID invoice, ledger row
151	  try {
152	    const invoiceId = await db.$transaction(async (tx) => {
153	      const flipped = await tx.dedicatedServer.updateMany({
154	        where: { id: s.id, renewalDate: period, cancelAtPeriodEnd: false },
155	        data: { renewalDate: next, renewalFailedAt: null, renewalAttempts: 0, renewalWarnedFor: null, ...(isUnpaidSuspension(s) ? { status: "ACTIVE" as const, suspendedAt: null, suspendReason: null } : {}) },
156	      });
157	      if (flipped.count !== 1) throw new AlreadyRenewed();
158	      await debitRealFunds(tx, user.id, total);
159	      await tx.walletTransaction.create({ data: { userId: user.id, amountCents: -total, description: what } });
160	      const inv = await tx.invoice.create({
161	        data: invoiceCreateData({
162	          userId: user.id,
163	          description: what,
164	          status: "PAID",
165	          lineItems: [{ description: `${s.label}: ${termLabel(s.termMonths)} renewal ${ymd(period)} to ${ymd(next)} (${renewalPriceText(s)})`, qty: 1, unitCents: net, amountCents: net }],
166	          taxCents,
167	          taxRatePercent: tax.ratePercent,
168	          taxCountry: taxCents > 0 ? tax.country || null : null,
169	          period: { start: period, end: next },
170	        }),
171	        select: { id: true },
172	      });
173	      await tx.dedicatedServer.update({ where: { id: s.id }, data: { invoiceIds: { push: inv.id } } });
174	      return inv.id;
175	    });
176	    await event(s.id, "renewed", `${usd(total)} (${viaCardCents ? `${usd(viaCardCents)} by card, ` : ""}rest from real wallet funds) invoice ${invoiceId}; next ${ymd(next)}${actor ? ` by ${actor}` : ""}${isUnpaidSuspension(s) ? "; suspension lifted" : ""}`);
177	    await deps.notify(s.userId, `${s.label} renewed`, `We charged ${usd(total)}. Next renewal ${ymd(next)}.`, serverHref(s.id));
178	    return { ok: true, invoiceId, chargedCents: total, viaCardCents, nextRenewal: next };
179	  } catch (e) {
180	    if (e instanceof AlreadyRenewed) return { ok: false, reason: "Already renewed for this period.", already: true };
181	    if (e instanceof PromoCreditNotAllowedError) return failed(s, deps, now, "no-real-funds", e.spendableCents, total);
182	    throw e;
183	  }
184	}
185	
186	class AlreadyRenewed extends Error {}
187	
188	async function failed(s: { id: string; userId: string; label: string; renewalDate: Date | null; status: string; renewalFailedAt: Date | null }, deps: BillingDeps, now: Date, why: string, spendableCents: number, total: number): Promise<RenewResult> {
189	  const cfg = await config();
